window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"letters","number":28,"source":"نامه 28.docx","mode":"explicit-parts","parts":["نامه 28\nبخش اول\nمتن:\nو من كتاب له (علیه السلام) إلى معاوية جواباً. [قال الشريف: و هو من محاسن الكتب]:\nأَمَّا بَعْدُ فَقَدْ أَتَانِي كِتَابُكَ تَذْكُرُ فِيهِ اصْطِفَاءَ اللَّهِ مُحَمَّداً (صلی الله علیه وآله) لِدِينِهِ وَ تَأْيِيدَهُ إِيَّاهُ لِمَنْ أَيَّدَهُ مِنْ أَصْحَابِهِ؛ فَلَقَدْ خَبَّأَ لَنَا الدَّهْرُ مِنْكَ عَجَباً إِذْ طَفِقْتَ تُخْبِرُنَا بِبَلَاءِ اللهِ تَعَالَى عِنْدَنَا وَ نِعْمَتِهِ عَلَيْنَا فِي نَبِيِّنَا، فَكُنْتَ فِي ذَلِكَ كَنَاقِلِ التَّمْرِ إِلَى هَجَرَ أَوْ دَاعِي مُسَدِّدِهِ إِلَى النِّضَالِ؛ وَ زَعَمْتَ أَنَّ أَفْضَلَ النَّاسِ فِي الْإِسْلَامِ فُلَانٌ وَ فُلَانٌ، فَذَكَرْتَ أَمْراً إِنْ تَمَّ اعْتَزَلَكَ كُلُّهُ وَ إِنْ نَقَصَ لَمْ يَلْحَقْكَ ثَلْمُهُ؛ وَ مَا أَنْتَ وَ الْفَاضِلَ وَ الْمَفْضُولَ وَ السَّائِسَ وَ الْمَسُوسَ، وَ مَا لِلطُّلَقَاءِ وَ أَبْنَاءِ الطُّلَقَاءِ وَ التَّمْيِيزَ بَيْنَ الْمُهَاجِرِينَ الْأَوَّلِينَ وَ تَرْتِيبَ دَرَجَاتِهِمْ وَ تَعْرِيفَ طَبَقَاتِهِمْ؟! هَيْهَاتَ، لَقَدْ حَنَّ قِدْحٌ لَيْسَ مِنْهَا وَ طَفِقَ يَحْكُمُ فِيهَا مَنْ عَلَيْهِ الْحُكْمُ لَهَا. أَ لَا تَرْبَعُ أَيُّهَا الْإِنْسَانُ عَلَى ظَلْعِكَ وَ تَعْرِفُ قُصُورَ ذَرْعِكَ وَ تَتَأَخَّرُ حَيْثُ أَخَّرَكَ الْقَدَرُ؟ فَمَا عَلَيْكَ غَلَبَةُ الْمَغْلُوبِ وَ لَا ظَفَرُ الظَّافِرِ؟ [فَإِنَّكَ] وَ إِنَّكَ لَذَهَّابٌ فِي التِّيهِ، رَوَّاغٌ عَنِ الْقَصْدِ.\nترجمه:\nاما بعد (از حمد و ثناى الهى) نامه ات به من رسيد نامه اى که در آن يادآور شده اى که خداوند محمد(صلى الله عليه وآله) را براى آيينش برگزيد و با اصحابش او را تأييد کرد. به راستى دنيا چه شگفتى هايى در خود از سوى تو براى ما نهفته؟ چرا که مى خواهى ما را از آنچه خداوند به ما عنايت فرموده آگاه سازى و به ما از نعمت وجود پيغمبر ما در ميان ما خبر دهى، کار تو به کسى مى ماند که خرما را (از نقاط ديگر) به سرزمين هَجَر (سرزمينى که مرکز خرما بود) مى برد، و يا همچون شاگرد تيراندازى که بخواهد از طريق دعوت به مبارزه، استادش را بيازمايد. تو گمان کردى که برترين اشخاص در اسلام، فلان و فلانند!\nمطلبى را يادآور شده اى که اگر راست باشد به تو مربوط نيست و اگر دروغ باشد زيانى به تو نمى رساند، اساساً تو را با برتر و غير برتر و رييس و زيردست چکار؟ اسيران آزاد شده از کفار زمان جاهليّت و فرزندان آنها را با امتياز نهادن ميان مهاجران نخستين و ترتيب درجات و تعريف طبقاتشان چه نسبت؟! هيهات! تو خود را در صفى قرار مى دهى که از آن بيگانه اى، کار به جايى رسيده که محکومى مى خواهد خودش به داورى بنشيند. اى انسان (غافل و بى خبر) چرا بر سر جاى خود نمى نشينى، و چرا از کوتاهى و ناتوانى خويش آگاه نيستى، و چرا به آنجا که مقدّرات براى عقب راندن تو تعيين کرده باز نمى گردى؟ تو را با غلبه مغلوب و پيروزى پيروزمند (در پيدايش و پيشرفت اسلام و بعد از رحلت پيامبر اکرم(صلى الله عليه وآله)) چکار؟ تو همان کسى هستى که همواره در بيابان (گمراهى) سرگردانى و از راه راست (و حد اعتدال) به اين طرف و آن طرف حرکت مى کنى.\nتفسیر:\n🔵و من کتاب له علیه السلام إلى معاویه جواباً. [قال الشریف: و هو من محاسن الکتب]:\nاین نامه در جواب نامه معاویه نوشته شده و طبق قول مرحوم سید رضی رضوان‌الله علیه  از بهترین و کاملترین نامه هاست. چه از جهت لحن و چه از لحاظ محتوا (هم شامل فضائل ائمه است، هم روضه دارد و هم پاسخی کوبنده به معاویه است و…)\nبرای روشن تر شدن نامه‌ی حضرت، ابتدا نامه معاویه را می‌خوانیم:\nابن ابی الحدید معتزلی در شرح نهج البلاغه خود می‌گوید که من از استادم ابو جعفر نقیب (شیعه) در مورد این نامه پرسیدم:\nبعد از مرگ عثمان، معاویه در صدد بر می‌آید تا با دستاویز قرار دادن پیراهن عثمان قتل او را به گردن امیرالمؤمنین بیاندازد و با ایجاد چنین فضایی بگوید علی از ابتدا با عمر و ابوبکر و سایر صحابی مشکل داشته و در فکر دشمنی و قتل آن دو نیز بوده،\n مسلمانان آن عصر از طرفداران خلفای قبل بودند و حضرت را به عنوان خلیفه چهارم مسلمین پذیرفته بودند نه امام جامعه، معاویه قصد داشت با التهاب بین آنان دشمنی ایجاد نماید.\nمعاویه در این نامه با کلماتی مثل حسادت و  قاتل خواندن حضرت در صدد ایجاد این التهاب است. \nاین نامه معاویه  در ادامه پاسخی است که حضرت در نامه ۹ به معاویه می‌دهند و اتهامات وارده از سوی معاویه را به صورت مستدل و کوبنده پاسخ می‌دهند. \nمعاویه بعد از دریافت نامه ۹ به مشورت با عمر و عاص می‌پردازد و  چون تیرشان به سنگ خورده مایوسانه به او گلایه میکند که عمر وعاص پاسخی از سر ندانستن جایگاه حضرت میدهد و حضرت را چنین توصیف میکند:\n🔺وقالَ لَهُ عَمرٌو : إنَّ عَلِیّاً علیه السلام رَجُلٌ نَزِقٌ تَیّاهٌ ،\nعلی مردی عجول و سردرگم است،\n ومَا استَطعَمتَ مِنهُ الکَلامَ بِمِثلِ تَقریظِ أبی بَکرٍ وعُمَرَ فَاکتُب\nهر چه میتوانی در مدح خلفا برای او بنویس تا او به خشم آید و جواب تندی به تو بدهد.\n(چرا که اگر حضرت پاسخ تندی به معاویه می‌دادند و از خلفا بدگویی می‌کردند موجب ناراحتی طرفداران خلفا میشد و همین یک دستاویز نو برای دشمنی با امیرالمؤمنین بود.\n🔺نامه مجدد معاویه به امیرالمومنین:\nمِن عَبدِ اللّهِ مُعاوِیَهَ بنِ أبی سُفیانَ إلى عَلِیِّ بنِ أبی طالِبٍ : \nاز بنده خدا معاویه بن ابوسفیان به علی بن ابوطالب.\n(با بی‌ادبی برای خود لقب عبدالله را برمی‌گزیند و امیر المؤمنین را بدون لقب و تنها با نام خطاب می‌کند) \nأمّا بَعدُ ؛ فَإِنَّ اللّهَ تَعالى جَدُّهُ ، اصطَفى مُحَمَّدا علیه السلام لِرِسالَتِهِ وَاختَصَّهُ بِوَحیِهِ وتَأدِیَهِ شَریعَتِهِ ،\nاما بعد، خداوند تعالی محمد را برای رسالتش برگزید و او را به وحی و ادای شریعت خود مخصوص گردانید، \nفَأَنقَذَ بِهِ مِنَ العَمایَهِ و هَدى بِهِ مِنَ الغَوایَهِ ، \nو به وسیله او از جهالت نجات داد و از گمراهی هدایت کرد\nثُمَّ قَبَضَهُ الَیهِ رَشیداً حَمیدا قَد بَلَّغَ الشَّرعَ ومَحَقَ الشِّرکَ وأخمَدَ نارَ الإِفکِ ، \n سپس او را رشید، قابل ستایش ،که شرع را تبلیغ، شرک را نابود و آتش دروغ را خاموش کرده است به سوی خود گرفت .\n(با بیان اوصاف پیامبر مقام امام علی علیه السلام را مورد هدف قرار می‌دهد) \nفَأَحسَنَ اللّهُ جَزاءَهُ وضاعَفَ عَلَیهِ نِعَمَهُ وآلاءَهُ ،\nپس خداوند جزای او را نیک گرداند و نعمت و برکات خویش را بر او دو چندان کند.\nثُمَّ إنَّ اللّهَ سُبحانَهُ اختَصَّ مُحَمَّدا علیه السلام بِأَصحابٍ أیَّدوهُ و آزَروهُ ونَصَروهُ ،\nسپس خداوند سبحان محمد را به یارانی مخصوص گردانید که او را تأیید، یاری و نصرت کردند.\n وکانوا کَما قالَ اللّهُ سُبحانَهُ لَهُم : «أَشِدَّآءُ عَلَى الْکُفَّارِ رُحَمَآءُ بَیْنَهُمْ» \nچنان بودند که خداوند متعال به آنان فرمود: « أَشِدَّاء عَلَی الْکُفَّارِ رُحَمَاء بَیْنَهُمْ» بر کافران سختگیر و بایکدیگر مهربانند.\nفَکانَ أفضَلَهُم مَرتَبَهً وأعلاهُم عِندَ اللّهِ وَالمُسلِمینَ مَنزِلَهً الخَلیفَهُ الأَوَّلُ ، الَّذی جَمَعَ الکَلِمَهَ و لَمَّ الدَّعوَهَ وقاتَلَ أهلَ الرِّدَّهِ ، \nو بلند مرتبه ترین آنان نزد خدا و مسلمانان خلیفه اول بود که اتحاد ایجاد کرد و دعوت را دوباره به دست گرفت و با اهل رده پیکار کرد،\nثُمَّ الخَلیفَهُ الثّانی الَّذی فَتَحَ الفُتوحَ ومَصَّرَ الأَمصارَ وأذَلَّ رِقابَ المُشرِکینَ ،\nسپس خلیفه دوم است که فتوحات را آغاز کرد و شهرها را آباد و مشرکان را خوار کرد.\n ثُمَّ الخَلیفَهُ الثّالِثُ المَظلومُ الَّذی نَشَرَ المِلَّهِ وطَبَّقَ الآفاقَ بِالکَلِمَهِ الحَنیفِیَّهِ .\nسپس خلیفه سوم مظلوم که دین را ترویج کرد و آفاق را با کلمه یکتا پرستی پر کرد.\n(به نحوی خلفا را مدح می‌کند که اگر کسی خلفا را نشناسد ذره ای شک نمی‌کند) \nدر ادامه به تخریب جایگاه حضرت میپردازد:\nفَلَمَّا استَوثَقَ الإِسلامُ وضَرَبَ بِجِرانِهِ  عَدَوتَ عَلَیهِ فَبَغَیتَهُ الغَوائِلَ ونَصَبتَ لَهُ المَکایِدَ ، \nو زمانی که اسلام استقرار یافت و ثبات پیدا کرد بر او دشمنی کردی و برای او مصیبتها خواستی و نیرنگ ها بر او بر پا کردی\nوضَرَبتَ لَهُ بَطنَ الأَمرِ وظَهرَهُ ودَسَستَ عَلَیهِ وأغرَیتَ بِهِ ، \n و از هر چیزی علیه او سود جستی و برای او دسیسه چیدی و او را تحریک کردی \nوقَعَدتَ حَیثُ استَنصَرَکَ عَن نَصرِهِ وسَأَلَکَ أن تُدرِکَهُ قَبلَ أن یُمَزَّقَ فَما أدرَکتَهُ ،\nو زمانی که از تو طلب یاری کرد او را یاری نکردی و از تو در خواست کرد که قبل از اینکه کشته شود کمکش کنی اما چنین نکردی .\nوما یَومُ المُسلِمینَ مِنکَ بِواحِدٍ .\n مصیبت مسلمانان از دست تو، یکی دوتا نیست،\nلَقَد حَسَدتَ أبا بَکرٍ و َالتَوَیتَ عَلَیهِ و رُمتَ إفسادَ أمرِهِ ، وقَعَدتَ فی بَیتِکَ ، \nبر ابوبکر حسادت کردی و بر او پیچیدی و تباه کردن امر او را هدف کردی و در خانه ات از او بازنشستی\nوَاستَغوَیتَ عِصابَهً مِنَ النّاسِ حَتّى تَأَخَّروا عَن بَیعَتِهِ ،\nگروهی از مردم را فریفتی تا اینکه از بیعت با او تأخیر کردند.\n ثُمَّ کَرِهتَ خِلافَهَ عُمَرَ وحَسَدتَهُ وَاستَطَلتَ مُدَّتَهُ ،\nسپس از خلافت عمر بیزاری جستی و بر او حسادت کردی و مدت را به درازا کشاندی.\n وسُرِرتَ بِقَتلِهِ وأظهَرتَ الشَّماتَهَ بِمُصابِهِ حَتّى إنَّکَ حاوَلتَ قَتلَ وَلَدِهِ ؛ لِأَنَّهُ قَتَلَ قاتِلَ أبیهِ ،\n به کشته شدن او شاد شدی و شادی از مصیبت او را نمایان ساختی حتی در کشتن پسرش (عبدالله بن عمر) به این دلیل که قاتل پدرش را کشته است تلاش کردی.\nثُمَّ لَم تَکُن أشَدَّ مِنکَ حَسَدا لِابنِ عَمِّکَ عُثمانَ \nسپس شدیدترین حسادت را برای پسر عمویت عثمان به خرج دادی،\nنَشَرتَ مَقابِحَهُ وطَوَیتَ مَحاسِنَهُ ، \nبدی های او را ترویج و نیکی های او را پنهان کردی\nوطَعَنتَ فی فِقهِهِ ثُمَّ فی دینِهِ ثُمَّ فی سیرَتِهِ ثُمَّ فی عَقلِهِ ، وأغرَیتَ بِهِ السُّفَهاءَ مِن أصحابِکَ وشیعَتِکَ حَتّى قَتَلوهُ\nدر فقه، دین، سیره سپس در عقل طعنه زدی و کم خردان اصحاب و پیروانت را علیه او تحریک کردی تا اینکه او را در حضور تو کشتند\n بِمَحضَرٍ مِنکَ لا تَدفَعُ عَنهُ بِلِسانٍ ولا یَدٍ ، \n درحالی که نه با دست و نه با زبان از او دفاع نکردی. \nوما مِن هؤُلاءِ (خلفا) إلّا مَن بَغَیتَ عَلَیهِ وتَلَکَّأتَ فی بَیعَتِهِ \nو کسی از اینان نیست مگر کسی که بر او ستم کردی و در بیعتش درنگ کردی\nحَتّى حُمِلتَ إلَیهِ قَهراً تُساقُ بِخَزائِمِ الاِقتِسارِ کَما یُساقُ الفَحلُ المَخشوشُ ، \n تا اینکه به اجبار بر آن واداشته شدی و چونان اسب دهن بسته با زمام های اکراه سوق داده شدی.\nثُمَّ نَهَضت الآنَ تَطلُبُ الخِلافَهَ ، \nسپس اینک در طلب خلافت به پاخواسته ای\nوقَتَلَهُ عُثمانَ خُلَصاؤُکَ وسُجَراؤُکَ والمُحدِقونَ بِکَ ، \nدر حالی که مخلصان و یاران و اطرافیانت قاتلان عثمان هستند \nوتِلکَ مِن أمانِیِّ النُّفوسِ وضَلالاتِ الأَهواءِ .\n و آن از آرزوهای نفس  و گمراهی  هواهاست.\nفَدَعِ اللَّجاجَ وَالعَبَثَ جانِباً وَادفَع إلَینا قَتَلَهَ عُثمانَ ،\nپس لجاجت وسختی را کنار بگذار و قاتلان عثمان را به ما تحویل بده\nوأَعِدِ الأَمرَ شورى بَینَ المُسلِمینَ لِیَتَّفِقوا عَلى مَن هُوَ للّهِ رِضاً . \nو امر را از روی مشورت بین مسلمانان از سر بگیر تا بر این که چه کسی مورد رضایت خداست توافق کنند\nفَلا بَیعَهَ لَکَ فی أعناقِنا ولا طاعَهَ لَکَ عَلَینا ولا عُتبى لَکَ عِندَنا ، \nنه برای تو بیعتی بر گردن ماست و نه طاعت از تو بر ماست و نه عتابی نزد ما برای توست.\nولَیسَ لَکَ ولِأَصحابِکَ عِندی إلَا السَّیفُ ،\n و برای تو و اصحاب تو جز شمشیر چیزی نزد من نیست،\n وَالَّذی لا إلهَ إلّا هُوَ لَأَطلُبَنَّ قَتَلَهَ عُثمانَ أینَ کانوا وحَیثُ کانوا حَتّى أقتُلَهُم أو تَلتَحِقَ روحی بِاللّهِ .\nو به خدایی که غیر از او خدایی نیست سوگند قاتلان عثمان را هر جا و هرگونه که باشند می⁭جویم تا آنان را بکشم یا روحم به خدا ملحق شود. \nفَأَمّا ما لا تَزالُ تَمُنُّ بِهِ مِن سابِقَتِکَ وجِهادِکَ\nو اما در خصوص آنچه که پیوسته در خصوص پیشینه و جهادت به خود منسوب می کنی،\n فَإِنّی وَجَدتُ اللّهَ سُبحانَهُ یَقولُ : «یَمُنُّونَ عَلَیْکَ أَنْ أَسْلَمُواْ قُل لَا تَمُنُّواْ عَلَىَّ إِسْلَـمَکُم بَلِ اللَّهُ یَمُنُّ عَلَیْکُمْ أَنْ هَدَاکُمْ لِلْاءِیمَـنِ إِن کُنتُمْ صَـدِقِینَ» \n خداوند سبحان در قران میفرماید: \n {از اینکه اسلام آورده اند بر تو منت می نهند بگو بر من از اسلام آوردنتان منت مگذارید، بلکه خداست که با هدایت کردن شما به ایمان بر شما منت می گذارد اگر راستگو باشید} \nولَو نَظَرتَ فی حالِ نَفسِکَ لَوَجَدتَها أشَدَّ الأَنفُسِ امتِناناً عَلَى اللّهِ بِعَمَلِها ، \nو اگر در حال خود بنگری آن را منت گذارترین نفس بر خدا به خاطر عمل خود میابی\nوإذا کانَ الاِمتِنانُ عَلَى السّائِلِ یُبطِلُ أجرَ الصَّدَقَهِ فَالاِمتِنانُ عَلَى اللّهِ یُبطِلُ أجرَ الجِهادِ \n و زمانیکه منت بر سائل اجر صدقه را از بین میبرد منت بر خدا نیز اجر جهاد را زائل می کند \n ویَجعَلُهُ کـَ«صَفْوَانٍ عَلَیْهِ تُرَابٌ فَأَصَابَهُ وَابِلٌ فَتَرَکَهُ صَلْدًا لَا یَقْدِرُونَ عَلَى شَىْ ءٍ مِّمَّا کَسَبُواْ وَاللَّهُ لَا یَهْدِى الْقَوْمَ الْکَـفِرِینَ»\nو آن را اینگونه قرار می دهد:\n «صَفْوَانٍ عَلَیْهِ تُرَابٌ» مَثَل صدقات[ کسانی که اموال خویش را برای طلب خشنودی خدا و استواری روحشان انفاق می کنند، همچون مَثَلِ باغی است که بر فرازبلندی قرار دارد که اگر رگباری بر آن برسد، دوچندان محصول برآورد، و اگر رگباری هم بر آن نرسد، باران ریزی برای آن بس است، و خداوند به آنچه انجام می دهید بیناست .\n(از بهترین صفات حضرت برای ضربه زدن به او استفاده می‌کند.)\nمتن نامه 28 در پاسخ به نامه معاویه:\n💠أَمَّا بَعْدُ فَقَدْ أَتَانِی کِتَابُکَ\nبعد از حمد و ثنای الهی…. نامه تو به دستم رسید\n💠 تَذْکُرُ فِیهِ اصْطِفَاءَ اللَّهِ مُحَمَّداً (صلی الله علیه وآله) لِدِینِهِ \nتو در نامه خود ذکر کردی که خداوند حضرت محمد را برای دینش برگزید. \n💠وَ تَأْیِیدَهُ إِیَّاهُ لِمَنْ أَیَّدَهُ مِنْ أَصْحَابِهِ؛ \nو خداوند به سبب اصحاب پیامبر، پیامبر را یاری کرد. \n💠فَلَقَدْ خَبَّأَ لَنَا الدَّهْرُ مِنْکَ عَجَباً \nمعاویه!  روزگار یک صفاتی از تو را بر ما پنهان کرده بود.[خَبَّأَ] \n(جمله کنایه ای است به معاویه با این مضمون که تو با این حد از فهم و سخنوری  تا به حال کجا بودی؟! \nمعنای معکوس دارد و طعنه ای است به او ) \n💠إِذْ طَفِقْتَ تُخْبِرُنَا بِبَلَاءِ اللهِ تَعَالَى عِنْدَنَا وَ نِعْمَتِهِ عَلَیْنَا فِی نَبِیِّنَا، \nتو آمده ای و به من از وجود پر نعمت[ببلاءِ] پیامبرمان سخن میگویی\n(بلاء تنها به معنای امتحان و سختی نیست بلکه از نعمت های الهی هم به بلاء تعبیر میشه.) \n💠فَکُنْتَ فِی ذَلِکَ کَنَاقِلِ التَّمْرِ إِلَى هَجَرَ\nمثال تو در بیان این نعمت برای من مانند کسی است که خرما [تَمر]به شهر هجر می‌برد. \n(هجر به عقیده برخی شهری است در یمن وبرخی آن را در بحرین میدانند.) \n 💠أَوْ دَاعِی مُسَدِّدِهِ إِلَى النِّضَالِ؛ \nیا مانند کسی است که استاد تیر اندازی را به مسابقه تیر اندازی دعوت می‌کند.\nدر مثال اول شهر هجَر شهری است مملو از خرما  که خرما در آن ارزان است، تاجری اهل شهر هجر موقع بازگشت از سفر تجاری خود در بصره از خرمای بصره که بسیار ارزان بوده می‌خرد و به شهر هجر می‌برد که آنجا هم خرما فراوان بوده و خرماهایش به فروش نمی‌رسد تا وقتی نزدیک به فساد بودند رایگان به مردم می‌دهد و از آن پس ضرب المثل می‌شود. \nچیزی مثل“ زیره به کرمان بردن“ در زبان فارسی\nاز نبی به علی گفتن مثل زیره به کرمان بردن است. \nدر مثال دوم تو مثل نو آموزی هستی که  استادش را به تیر اندازی دعوت کرده تا اگر تیر تو  به من خورد بگویی از سر نا واردی بوده. \n💠وَ زَعَمْتَ أَنَّ أَفْضَلَ النَّاسِ فِی الْإِسْلَامِ فُلَانٌ وَ فُلَانٌ،\nتو خیال کردی بالاترین مردم در اسلام فلان و فلان است\n(حضرت حتی از دو خلیفه اسم هم نمیبرند.)\n 💠فَذَکَرْتَ أَمْراً إِنْ تَمَّ اعْتَزَلَکَ کُلُّهُ \nتو حرفی را ذکر کردی که به فرض که درست باشد به تو ارتباطی ندارد و سودی به تو نمیرساند. \n💠وَ إِنْ نَقَصَ لَمْ یَلْحَقْکَ ثَلْمُهُ؛\nاگر هم درست نباشد باز هم ضرری تو را تهدید نمی‌کند.\nامور صحابه : \n💠 وَ مَا أَنْتَ وَ الْفَاضِلَ وَ الْمَفْضُولَ وَ السَّائِسَ وَ الْمَسُوسَ،\nتو را چه به این که بالا چه کسی و پایین می چه کسی است؟ [الْفَاضِلَ وَ الْمَفْضُولَ] رئیس چه کسی است و مرئوس چه کسی است؟[السَّائِسَ وَ الْمَسُوسَ،] \n💠 وَ مَا لِلطُّلَقَاءِ وَ أَبْنَاءِ الطُّلَقَاءِ وَ التَّمْیِیزَ بَیْنَ الْمُهَاجِرِینَ الْأَوَّلِینَ وَ تَرْتِیبَ دَرَجَاتِهِمْ وَ تَعْرِیفَ طَبَقَاتِهِمْ؟!\nتو جزء آزادشدگان و فرزندان آنهایی[طُّلَقَاءِ] (مشرکانی که پیامبر بعد از فتح مکه آنها را از روی رأفت اسلامی آزاد کرد و به زور اسلام آوردند) تو را چه به مشخص کردن درجات و طبقه‌ی مهاجرین و صحابه؟ \n✅بنا به گفته حضرت در نامه ۱۶ انها فقط کفرشان را پنهان کردند و مسلمان نیستند:\nفَوَ الَّذِی فَلَقَ الْحَبَّهَ وَ بَرَأَ النَّسَمَهَ مَا أَسْلَمُوا وَ لَکِنِ اسْتَسْلَمُوا وَ أَسَرُّوا الْکُفْرَ، فَلَمَّا وَجَدُوا أَعْوَاناً عَلَیْهِ أَظْهَرُوه\nبه خدایى که دانه را شکافت و انسان را به وجود آورد، اینان از روى حقیقت اسلام نیاوردند، اسلامشان از روى ترس بود و کفر را در درون خود پنهان داشتند، و چون یار و یاور یافتند آن را ظاهر نمودند.\n💠 هَیْهَاتَ، لَقَدْ حَنَّ قِدْحٌ لَیْسَ مِنْهَا وَ طَفِقَ یَحْکُمُ فِیهَا مَنْ عَلَیْهِ الْحُکْمُ لَهَا. \n (( نالهٔ [حنَّ، حنین]چوب [قدحُ] خود را مفتضح کرد ، یک ضرب المثل است.\nدر جاهلیت برای قرعه کشی چوبه تیر که هر کدام معنای خاص دارد همه چوبها یک وزن و یک حجم ، یک شکل و یک اهنگ خاص در کیسه تکان میدادند قرعه ای برمی داشتند ، اگر یک شی نامربوط در داخل کیسه کنار چوبها صدای ناموزون ان واضح و عیان است .))  [لقد حنَّ قدحُ]\nهیهات ! شروع کرد[طفِقَ] به حکم صادر کردن ، کسی که خود محکوم است [لیس منها] در تعیین برتری صحابه پیامبر، کسی که خود محکوم است نمی‌تواند در این جریان قاضی باشد و حکم کند.\nمعاویه تو که جزء سابقین و صحابی نبودی فقط رسوایی و افتضاح شدن خود را فریاد میزنی .خود را بیشتر خراب میکنی.\nمعاویه از نظر ادبی در میان عرب ممتاز بود و اشعار او گرچه مضمون باطل دارد اما غنی و ساخته پرداخته فنی دارد.\nلذا امام او را با ضرب المثل عمیق\nکه در عرب مرسوم است پاسخ می دهد.\n💠أَ لَا تَرْبَعُ أَیُّهَا الْإِنْسَانُ عَلَى ظَلْعِکَ وَ تَعْرِفُ قُصُورَ ذَرْعِکَ\nای انسان چرا به لنگان بودن پایت [ظلعِک]متوقف نمی‌شوی[اَلا تَربع] \nای انسان کوتاهی دست خود و عدم توانایی و قدرت [قصورَ ذرعِک]را بشناس! \nدست تو به نخل نمیرسد و در قد و قواره خلافت پیامبر نیستی ، تو برای حکومت و خلافت خیلی کوچکتر و ناتوان تری. \n 💠وَ تَتَأَخَّرُ حَیْثُ أَخَّرَکَ الْقَدَرُ؟\nعقب بنشین در آنجایی که قضا و قدر تو را به عقب انداخت. \n(حضرت حتی در دلسوزی، هدایت و نصیحت دشمنانش هم  کوتاهی نمیکند.) \n💠فَمَا عَلَیْکَ غَلَبَهُ الْمَغْلُوبِ وَ لَا ظَفَرُ الظَّافِرِ؟ \nچه ربطی به تو دارد پیروزی و شکست دیگران؟ \n💠وَ إِنَّکَ لَذَهَّابٌ فِی التِّیهِ، \nمعاویه تو کسی هستی که به شدت در بیابان سرگردانی [تیه]رها شدی. \n💠رَوَّاغٌ عَنِ الْقَصْدِ.\nتو در مسیر حق نیستی و مدام به چپ و راست در حرکتی.[روّاغ]\n(روغ به حرکت زیکزاکی روباه می‌گویند برای تله نیفتادن.)\nبا زیرکی و به خاطر نفع و سودت  یکبار از صحابی دفاع میکنی و وقتی به من که از اصحاب پیامبرم میرسی به نفع خودت مخالفت میکنی.\nاللهم اهدنا الی سواء السبیل","بخش دوم\nمتن:\nأَ لَا تَرَى -غَيْرَ مُخْبِرٍ لَكَ وَ لَكِنْ بِنِعْمَةِ اللَّهِ أُحَدِّثُ- أَنَّ قَوْماً اسْتُشْهِدُوا فِي سَبِيلِ اللَّهِ تَعَالَى مِنَ الْمُهَاجِرِينَ وَ الْأَنْصَارِ وَ لِكُلٍّ فَضْلٌ، حَتَّى إِذَا اسْتُشْهِدَ شَهِيدُنَا قِيلَ سَيِّدُ الشُّهَدَاءِ وَ خَصَّهُ رَسُولُ اللَّهِ (صلی الله علیه وآله) بِسَبْعِينَ تَكْبِيرَةً عِنْدَ صَلَاتِهِ عَلَيْهِ. أَ وَ لَا تَرَى أَنَّ قَوْماً قُطِّعَتْ أَيْدِيهِمْ فِي سَبِيلِ اللَّهِ وَ لِكُلٍّ فَضْلٌ، حَتَّى إِذَا فُعِلَ بِوَاحِدِنَا مَا فُعِلَ بِوَاحِدِهِمْ قِيلَ الطَّيَّارُ فِي الْجَنَّةِ وَ ذُو الْجَنَاحَيْنِ؛ وَ لَوْ لَا مَا نَهَى اللَّهُ عَنْهُ مِنْ تَزْكِيَةِ الْمَرْءِ نَفْسَهُ لَذَكَرَ ذَاكِرٌ فَضَائِلَ جَمَّةً تَعْرِفُهَا قُلُوبُ الْمُؤْمِنِينَ وَ لَا تَمُجُّهَا آذَانُ السَّامِعِينَ؛ فَدَعْ عَنْكَ مَنْ مَالَتْ بِهِ الرَّمِيَّةُ؛ فَإِنَّا صَنَائِعُ رَبِّنَا وَ النَّاسُ بَعْدُ صَنَائِعُ لَنَا.\nلَمْ يَمْنَعْنَا قَدِيمُ عِزِّنَا وَ لَا عَادِيُّ طَوْلِنَا عَلَى قَوْمِكَ أَنْ خَلَطْنَاكُمْ بِأَنْفُسِنَا فَنَكَحْنَا وَ أَنْكَحْنَا فِعْلَ الْأَكْفَاءِ وَ لَسْتُمْ هُنَاكَ، وَ أَنَّى يَكُونُ ذَلِكَ [كَذَلِكَ]، وَ مِنَّا النَّبِيُّ وَ مِنْكُمُ الْمُكَذِّبُ، وَ مِنَّا أَسَدُ اللَّهِ وَ مِنْكُمْ أَسَدُ الْأَحْلَافِ، وَ مِنَّا سَيِّدَا شَبَابِ أَهْلِ الْجَنَّةِ وَ مِنْكُمْ صِبْيَةُ النَّارِ، وَ مِنَّا خَيْرُ نِسَاءِ الْعَالَمِينَ وَ مِنْكُمْ حَمَّالَةُ الْحَطَبِ، فِي كَثِيرٍ مِمَّا لَنَا وَ عَلَيْكُمْ؛ فَإِسْلَامُنَا [مَا] قَدْ سُمِعَ وَ جَاهِلِيَّتُنَا لَا تُدْفَعُ وَ كِتَابُ اللَّهِ يَجْمَعُ لَنَا مَا شَذَّ عَنَّا، وَ هُوَ قَوْلُهُ سُبْحَانَهُ وَ تَعَالَى \"وَ أُولُوا الْأَرْحامِ بَعْضُهُمْ أَوْلى بِبَعْضٍ فِي كِتابِ اللَّهِ\"، وَ قَوْلُهُ تَعَالَى \"إِنَّ أَوْلَى النَّاسِ بِإِبْراهِيمَ لَلَّذِينَ اتَّبَعُوهُ وَ هذَا النَّبِيُّ وَ الَّذِينَ آمَنُوا وَ اللَّهُ وَلِيُّ الْمُؤْمِنِينَ\"؛ فَنَحْنُ مَرَّةً أَوْلَى بِالْقَرَابَةِ وَ تَارَةً أَوْلَى بِالطَّاعَةِ. وَ لَمَّا احْتَجَّ الْمُهَاجِرُونَ عَلَى الْأَنْصَارِ يَوْمَ السَّقِيفَةِ بِرَسُولِ اللَّهِ (صلی الله علیه وآله) فَلَجُوا عَلَيْهِمْ، فَإِنْ يَكُنِ الْفَلَجُ بِهِ فَالْحَقُّ لَنَا دُونَكُمْ، وَ إِنْ يَكُنْ بِغَيْرِهِ فَالْأَنْصَارُ عَلَى دَعْوَاهُمْ.\nترجمه:\nمن نمى خواهم (درباره فضايل بنى هاشم) به تو خبر دهم بلکه به عنوان سپاس و شکرگزارى نعمت خداوند بازگو مى کنم، آيا تو نمى بينى گروهى از مهاجران و انصار که در راه خداوند شربت شهادت نوشيدند هر کدام داراى مقام و مرتبتى شدند; اما هنگامى که شهيد ما حمزه به شهادت رسيد به او «سيّدالشّهدا» گفته شد (سرور شهيدان راه خدا) و رسول الله(صلى الله عليه وآله) هنگام نماز بر او (به جاى پنج تکبير) هفتاد تکبير گفت. آيا نمى بينى گروهى دستشان در ميدان جهاد قطع شد و هر کدام (در اسلام) مقام و منزلتى پيدا کردند; ولى هنگامى که اين جريان درباره يکى از ما رخ داد، لقب «طيار»، پروازکننده در آسمان بهشت با دو بال، به او داده شد و اگر نه اين بود که خداوند نهى از خودستايى کرده، گوينده اى (اشاره به خود امام است) فضايلى را برمى شمرد که دل هاىِ مؤمنان آگاه با آن آشناست و گوش هاى شنوندگان از شنيدن آن ابا ندارد، بنابراين دست از اين سخنان بردار و گمراهان را از خود دور کن (و بدان) ما برگزيده و پرورش يافته و رهين منّت پروردگار خويش هستيم و مردم پرورش يافتگان و تربيت شدگان و رهين هدايت ما هستند.\nهرگز عزت ديرين و عطاياى پيشينِ ما بر قوم و قبيله شما (بنى اميه) مانع نشد که ما با شما آميزش و اختلاط داشته باشيم به همين دليل ما از طايفه شما همسر گرفتيم و از دختران قبيله خويش به شما همسر داديم همچون اقوامى که هم طراز همند، در حالى که شما هرگز در اين پايه نبوديد. چگونه مى توان اين دو گروه را با هم يکسان دانست در حالى که از ميان ما پيامبر اکرم(صلى الله عليه وآله) برخاست و از ميان شما تکذيب کننده (اى همچون ابوجهل)، از ميان ما شير خدا (حمزه) و از ميان شما شير پيمان هاى ضد اسلامى (ابوسفيان) از ميان ما دو سرور جوانان بهشت (حسن و حسين(عليهما السلام)) و از ميان شما کودکان آتش (اولاد مروان و فرزندان عقبة بن ابى معيط) از ما بهترين زنان جهان (فاطمه(عليها السلام)) و از شما حمالة الحطب (ام جميل همسر ابولهب و خواهر ابوسفيان) و امور فراوان ديگر از فضايلى که ما داريم و رذايلى که شما داريد، بنابراين دوران اسلام ما به گوش همه رسيده و کارها و شرافت ما در عصر جاهليّت نيز بر کسى مخفى نيست.\nکتاب خدا آنچه را (دشمن) از ما دور ساخته براى ما جمع نموده است و شاهد آن سخن خداوند متعال است که فرموده: «خويشاوندان در کتاب الهى نسبت به يکديگر، در احکامى که خدا مقرر داشته، (از ديگران) سزاوارترند» و نيز فرموده: «سزاوارترين مردم به ابراهيم کسانى هستند که از او پيروى کردند، و همچنين اين پيامبر (که راه پر افتخار او را ادامه داد) و کسانى که به او ايمان آورده اند، و خداوند، سرپرست و ياور مؤمنان است»، پس ما از يک طرف به سبب قرابت و خويشاوندى (پيامبر(صلى الله عليه وآله)) از ديگران سزاوارتريم و از سوى ديگر به سبب اطاعت (از پيغمبر اکرم(صلى الله عليه وآله)) زيرا آن روز که مهاجران، در سقيفه در برابر انصار (براى اثبات حقانيّت خود نسبت به خلافت) استدلال به قرابت و خويشاوندى با پيامبر(صلى الله عليه وآله) کردند و بر آنها پيروز شدند اگر اين دليلِ پيروزى است پس حق با ماست نه با شما (چرا که ما از همه به پيامبر(صلى الله عليه وآله) نزديک تريم) و اگر دليل ديگرى داشتند ادعاى انصار بر جاى خود باقى است (و آنها هم در خلافت حقى دارند که آن را به عنوان «مِنّا أميرٌ وَمِنْکُمْ أميرٌ» مطالبه مى کردند).»\nتفسیر:\nمعاویه با گستاخی وتندی نامه نوشت که موحب خشم امیرالمومنین شود و بر علیه خلفا چیزی بگوید تا معاویه بدین وسیله  مردم را تحریک کرده بر علیه امام بشوراند چون مردم درآن عصر طرفدار خلفا بودند و حضرت را بعنوان خلیفه چهارم پذیرفته بودند.\nاما امام پاسخ عقلی و مستدل میدهد که معاویه ناکام میماند. \n💠 اَلا تَریٰ غیرَ مُخبرٕ لک ولکن بنعمهِ اللهِ اُحدِث\nمعاویه تو فضلی در اسلام نداری .\nچند فضیلت ازبنی هاشم بگویم ،تو لایق آن نیستی که به تو خبر و گزارش بدهم .\nولیکن من از نعمتهای الهی بر خودم باد آوری می کنم.[اُحدثَ]\nحضرت جملات کوبنده و در عین رعایت احترام به معاویه پاسخ میدهد‌\nبا ببان فضائل خود ستایی نمیکنم لکن نعمت خدا را بیان میکنم .\n💠اَنَ قوماً اِستُشهِدوا فی سبیل الله من المهاجرین\nدر تمام مدت اسلام مهاجرین و انصار بشهادت رسیدند. هر کدام از شهدا جایگاهی دارند‌ اما اگر یک شهید حمزه عموی ما ، از خاندان بنی هاشم بود سیدالشهدا می شود.\nاما تو ، پدر و برادرانت همه مخالف اسلام و پیغمبر بودید.چه فضیلتی برما داری.\n💠وخَصَهُ رسول الله \nما خاندان خاص و شما هم در شرارت یک خاندان خاص و هرگز ما دو خاندان قابل مقایسه نیستیم.\n ماکسانی هستیم که در شهادت عمویم حمزه پیامبر خدا در نماز میت او هفتاد مرتبه تکبیر گفت.\n✳️ مرحوم کلینی در کتاب کافی  بابی دارد ” مَن زادَ عَلیَ خَمسِ تکبیراتِ “\nعده ای که اهل ببت در نماز میت انها بیش از پنج تکبیر گفتند یکی از آنها حمزه شهید است.\nدر این قول اختلاف است که پیامبر در یک نماز میت ۷۰ بار تکبیر گفت .\nیا ۱۴ مرتبه نماز را جداگانه خواند هر بار ۵ تکبیر مجموع ان ۷۰ بار میشود. \nروایت دارد که ملائک فوج فوج می آمدند و پیامبر (ص) با آنها بر پیکر حمزه نماز میخواند.\nدر مورد شخصیت حمزه نکاتی وجود دارد:\n✳️ سید الشهدا بودن حمزه تا قبل از کربلا بود، بعد ازشهادت درکربلا وجود نازنین  حسین بن علی لقب سید الشهدا را گرفت.\nابن ابی الحدید در این مورد جمله زیبایی دارد .\n– حمزه سید الشهدا زمان پیامبر است .\n– حسین رن علی سید الشهدا زمان بعد از پیامبر است.\n– ولی علی بن ابیطالب سید الشهدا طول تاریخ است.\n✳️ فضائل حمزه سید الشهدا بسیار فراوان است.\nیُرفعُ یومَ القیمهِ اِلی علیِِ لِواءُ الحمد\nخدای متعال روز قیامت پرچم حمد را بدست امیرالمومنین میدهد.\n و اِلیَ الحمزهِ لِواءُ التکبیر\nو پرچم تکبیر را بدست جناب حمزه .\nو اِلی جعفرِِ لِواءُ التسبیح \n و بدست جعفر بن ابطالب پرچم تسبیح را میدهد.\nنمود علی در حمد و حمزه در تکبیر و جعفر در تسبیح است.\n✳️ روایت : \nیَاتِی بالرَّومِ الذی کانَ یُقاتِلُ حمزه اَعداءُ الله\nروز قیامت امیرالمومنین نیزه ای که حمزه با او در جنگها می جنگید و دشمنان را قلع و قمع میکرد.نیزه را بدست حمزه میدهد می فرماید: \nیا عَمَّ رسولِ الله ضِدِ الحجیم عَن اَولیاءِک بِرَوحِک \nعمو جان اولیا و دوستان پیامبر را با این نیزه از کنار آتش دوزخ نجات بده \n(مقام شفاعت است.)\n✳️ روایت : \nوقتی با ان وضعیت حمزه را مثله و شهید کردند پیامبر کنار جسد او ایستاد و فرمود: \nرَحِمَکَ الله اَی عَمِِ لَکنتَ وُصولَ بالرَّحِم صُعُولَ فیِ الخیرات\nعمو جان تو کسی بودی که صله رحم را بجا آوردی و غرق در کار خیر بودی .از هیچ کار خیری رویگردان نبود.\n✳️ روایت : \nپیامبر بعد از جنگ. وارد شهر مدینه شدند دیدند هر خانواده ای برای شهید خود گریه و عزاداری میکند.ولی حمزه کسی را ندارد بر او گریه کند. فرمود: \nحمزه لا مَواکِیَ لهُ \nایا حمزه شهید نیست بر او گریه کننده نیست.\nابن اثیر نقل می کند از زمان پیامبر تا اکنون که من هستم در مکه و مدینه رسم است هر کس قبل از گریه بر مصیبت و شهید خود، ابتدا بر مصیبت حمزه گریه میکند بعد گریه بر عزیز خود دارد.\nهمانند جایگاهی که ما اکنون بر ابا عبدالله قائلیم .حمزه چنین جایگاه والایی دارد.\n✳️ روایت: \nکسی که اولین تسبیح را اختراع کرد صدیقه کبری سلام الله علیها بود که ابتدا نخی بود گره های متعددی در او زده بود به تعداد تسبیحات.\nبعد از شهادت جناب حمزه از تربت و خاک قبر گلی برداشت و تسبیح درست کرد که بعد از آن با تربت او تسبیحات می گفت. و بعد از آن تربت ابا عبد الله اعلای تسبیحات شد.\n✳️ روایت امام باقر علیه السلام: \nشخصی پرسید بنی هاشم قوی و شجاع بودند زیر بار ظلم نمی رفتند جریان چه شد که کناره گیری کردند و حکومت بدست خلفا رسید و امیرالمومتین خانه نشین شد ؟! \nامام باقرعلیه السلام فرمود: \nاَما وَالّلهِ لَو اَنَّ حمزهَ و جعفرِِ کانا بِحَضرَتِهِما ما وَصَلا اِلی ما وَصَلا اِلیهِ\nاگر امیرالمومنین دو یار جعفر و حمزه را داشت بخدا قسم جریان خلافت کنار میرفت آنقدر که شجاع ، قوی و صاحب هیمنه بودند . کسی نبود جد ما را یاری کند.\n💠اَوَلا تَریٰ اَنَ قوماً قُطِعَت ایدیهِم \nدر تمام مدت اسلام عده ای دست قطع و جانباز شدند.همه درپیشگاه خدا اجر دارند\nاگر یکی از خاندان ما در این مسیر قطع دست شد.به او میگویند جعفر طیار ،ذو الجناحین.او دیگر شخص عادی نیست .\nجانباز ما دو بال در بهشت میگیرد.و پرواز میکند. تو خود را با ما مقایسه نکن.\nقبل از شهادت جعفر پیامبر لقب طیار را به او داد که تو در بهشت صاحب بال هستی و پرواز می کنی..\nبعد از شهادت وقتی پیامبر برای عرض تسلیت بخانه او رفت به همسر او اسماء بنت عُمیس بشارت را داد.\nاَلا اِنَّ جعفر قَدِ استُشهِدَ ….یَطیرُ بجَناحَیهِ  اِلیَ الجنَّه \nاو حاتباز و شهید شد ولی در عوض خدا دو بال برای او در بهشت مقرر کردکه پرواز می کند.\n✅ اسماء بنت عُمیس بانوی با شخصیت که در روضه های غسل حضرت زهرا  نام او برده میشود. بعد از شهادت جعفر طیار این بانو با خلیفه اول ازدواج کرد حاصل آن محمد بن ابی بکر بود و بعد از رحلت خلیفه با امیرالمومنین ازدواج کرد.و محمد در خانه حضرت پرورش پیدا کردو بزرگ شد.\nاسمادر شام شهادت حضرت زهرا در تغسیل حضرت را همراهی کرد، با اینکه همسر خلیفه بود به این خانه رفت و آمد داشت. نفوذی بود اخبار دربار خلافت را برای حضرت می آورد و حضرت دورادور ناظر بود مبادا ریشه ی دین را بزنند.\n✳️ روزی که قلعه خیبر بدست مبارک حضرت فتح شد جعفر بن ابیطالب مبلّغ دین از حبشه برگشت. خبر به پیامبر رسید قلعه فتح شد و جعفر برگشت. فرمود: \nما اَدرِی باَیِّهِما ما اَشَدُّ فَرحهً قُدومِ جعفرِ اَو بفتحِ خیبرِ \nنمیدانم بکدامیک از این دو مسرور باشم. بفتح یا آمدن جعفر.\nارزش مبلّغ و رساننده ی دین با فتح قلعه خیبر که چشم یهود را کور کرد، و دست یهود را از جامعه مسلمین قطع کرد، برابری می کند.\nجعفر طیار آنقدر رسیدگی به ضعفا و مساکین داشت که به او لقب ابو المساکین داده بودند.  پیامبر در مورد او فرمود: \nاَشبَهَت خلقاً و خُلقی\nجعفر در خلقت و خُلق شبیه به رسول الله است. همانگونه که در مورد علی اکبر علیه السلام امده: \nاشبَهُ الناس خلقا و خُلقاً برسولِ الله\n✳️ روایت : \nأَوْحَى اَللَّهُ تَعَالَى إِلَى رَسُولِ اَللَّهِ (ص) أَنِّی شَکَرْتُ لِجَعْفَرِ بْنِ أَبِی طَالِبٍ أَرْبَعَ خِصَالٍ\nخدا وحی کرد بر پیامبر ، جعفربن ابیطالب را دوست میدارم و از او سپاسگزارم .\nبنده ی خوبی که چهار خصلت دارد‌.\n فَدَعَاهُ اَلنَّبِیُّ صَلَّى اللَّهُ عَلَیْهِ وَ آلِهِ فَأَخْبَرَهُ \nپیامبر او را خبر داد و چهار خصلت او را پرسید \nفَقَالَ لَوْ لاَ أَنَّ اَللَّهَ تَبَارَکَ وَ تَعَالَى أَخْبَرَکَ مَا أَخْبَرْتُکَ\nگفت: اگر خدا نفرموده بودهرگز این خصلت را نمی گفتم .\n۱. مَا شَرِبْتُ خَمْراً قَطّ\nهرگز شراب نخوردم حتی در جاهلیت \nلِأَنِّی عَلِمْتُ أَنِّی إِنْ شَرِبْتُهَا زَالَ عَقْلِی\nمیدانستم اگر بنوشم عقل را زائل می کند. \n۲. وَ مَا کَذَبْتُ قَطُّ\nهرگز دروغ نگفتم چه پیش از اسلام ، چه بعد از اسلام. \nلِأَنَّ اَلْکَذِبَ یَنْقُصُ اَلْمُرُوءَهَ\nمیدانستم دروغ با جوانمردی نمی سازد. جوانمرد دروغ نمی گوید. \n۳. وَ مَا زَنَیْتُ قَطُّ\nهیچگاه بی عفتی نکردم \n لِأَنِّی خِفْتُ أَنِّی إِذَا عَمِلْتُ عُمِلَ بِی\nترسیدم اگر بی عفتی کنم در مورد من و خانواده ام بی عفتی کنند. هرگز بسمت گناه نرفتم. \n۴. وَ مَا عَبَدْتُ  صَنَماً قَطُّ\nهرگز مشرک نبودم حتی در جاهلیت  \nلِأَنِّی عَلِمْتُ أَنَّهُ لاَ یَضُرُّ وَ لاَ یَنْفَعُ\nمیدانستم هیچ نفعی بر من نیست و ضرری را از من دفع نمی کند. \n وَ قَالَ حَقٌّ لِلَّهِ تَعَالَى أَنْ یَجْعَلَ لَکَ جَنَاحَیْنِ تَطِیرُ بِهِمَا مَعَ اَلْمَلاَئِکَهِ فِی اَلْجَنَّهِ .\nسزاوار است که خدا دو بال به جعفر بدهد که با ملائک پرواز کند.\nادامه نامه ۲۸: \n💠ولو لا ما نَهَی اللهُ عنهُ مِن تَزکیَهِ المَرء نفسَه\nاگر خدا از خود ستایی نهی نکرده بود، که شخص خود ستایی کند.و از محاسن خود بگوید نهی نشده بود. فضائل کثیری بیان می کردم .فضائل زیادی که مومنین می شناسند.\n💠ولا تَمُجُها اذانُ الّسامِعیِن\nحتی کسانی که مخالف هستند، فضائل را میشنوند [سامعین] نمی‌توانند این فضایل را انکار کنند.و نسبت به آن استبعادی ندارند . از مومنین نیستند وقتی می شنوند قبول می کنند.وتو هیچکدام از این فضائل را نداری.\n✅نفرمود ، من هستم یا حمزه عموی من، جعفر برادر من، بلکه فرمود: \nحمزه سید الشهدا، جعفر طیار، و یک نفر هم هست [المَرء نفسَه] اگر بگوید فضائل زیاد است ولی ترس دارد مبادا خود ستایی شود.[ولکن بنعمهِ الله اُحدِث]\n《فلا تُزَکوا اَنفسَکُم هم اَعلَمُ بِمَنِ التَّقی ؛ نجم – ۳۲ 》\nخود ستایی نکنید که خداوند شما را بهتر می شناسد.\nفران خود ستودن را نهی کرده ولی در جایی باید فضائل را گفت ، \nمانند:  پزشک برای درمان خود را معرفی می کند ستودن نیست ، راه درمان را میداند تا بیان نکند کسی اعتماد نمی کند. \n✳️ شخصی از امام صادق صلواه الله علیه پرسید‌: آیا جایز است کسی از خود تعریف کند؟!\nفرمود: نعَم اِذَا اضطُرَّ ما علیه\nجایی که اضطرار و نیاز است باید گفته شود.\nیوسف پیامبر ابتدا جایگاه و تخصص خود را نشان میدهد تا مسئولیتی را عهده دار شود.فرمود: \n《قالَ اجعَلنِی علیَ خزائِنِ الارض اِنِّی حفیظُ علیم ؛ یوسف – ۵۵ 》  \nخود را به حافظ و عالم بودن معرفی میکند . مرا خزانه دار قرار دهید که امانتدار و عالم به خزانه داری هستم . فرمود: اگر فضائلی را بازگو می کند برای خود ستایی نیست مگر مشخص شدن جایگاه امامت.\nحضرت امیر در ذم خلفا چیزی نمی گوید ولی مدح را از خاندان اهل بیت و فضائل را از این خاندان میداند.\n💠فَدَعْ عنکَ مَن مالَت بهِ الرَّمیَّه\n ( رمیَّه :گم شدن صیاد در بیابان ،شکار صیاد را بدنبال خود می کشد‌ )\nمعاویه رها کن امثال عمرو عاص ، مغیره و مروان را، آنها دور تو هستند تا به اهداف خود برسند.منحرفند و انحراف تورا بیشترمیکنند.\n💠فاِنا صَنائِعُ ربِنا والناسُ بعدُ صنائِعُ لنا\nما کسانی هستیم که مستقیما از وحی درس گرفته و پرورش یافتیم [صنائعُ ربنا]\nومردم برای رشد و کمال راهی تدارند، باید از ما تبعیت کنند و پرورش بیابند.[صنائع لنا]\n✅جمله مهمی است که :\nالف) جایگاه والای اهل بیت را مشخص می کند.\nعلم ، وحی ، حکمت، عقل ، را به مردم فرا می دهیم . هر راهی غیر از این راه بن بست دارد و به بیراهه میرسد. مسیر  باید از راه اهل بیت علیهم السلام باشد .\nقران در مورد موسی بن عمران فرمود: \n(واصطَنَعتُکَ لِنفسِی)\nموسی تو را برای خود تربیت کردم .\nاز کلمه “صنائع ، تربیت کردن ” است.\nب) گروهی هم از این جمله راه ناصواب را گرفتند . خواسته اند از این جمله صانع بودن را بیان کنند.\nصانع ، صنعتگر ، خلق کننده ، خواستند بگویند اهل بیت خالق ما هستند.\n“صنائع ربنا” اهل بیت مخلوق خدایند\n” الناس صنائعُ لنا ”  و مردم مخلوق اهل بیت هستند.\nکه برداشت بسیار اشتباهی هست و امیرالمومنین با همین غلو کنندگان سخت مبارزه می کند. فرمود:\n« هلکَ فیَّ اِثنان مُحبٌ غالٌ و مُبغضٌ قال» \n دو گروه در مورد من به خطا رفتند.\n – غلو کنندگان ،در حد خدایی بالا میبرند.\n– و گروهی که حق علی را نشناخته پایین آوردند.\n به خیر و سعادت نمی رسند و هلاک شده هستند.\nامام صادق علیه السلام فرمود: \nما را خدا ندانید ، بیش از حد (تا خدایی) ما را بالا نبرید. ما مخلوق خدا هستیم.\nغیر از خدایی هر فضایلی و معروفی را خواستید نسبت بدهید.\nهر چه به ذهن شما برسد باز کم است.\n✅این جمله دو وجه دارد.\nاگر متظور این باشد که اهل بیت واسط خیر و فیض هستند حرف درست است. روایات هم تایید می کند.\nولی اگر اهل بیت خالق مردم ، منظور باشد، با صریح آیات و روایات نمی سازد‌\n💠لم یَمنَعنا قدیمُ عِزِنا ولا عادیُ طَولِنا\nاگر چه بنی هاشم از نظر عزت و شرافت با بنی امیه متفاوت است ،اما این برتری مانع نشد دو طایفه مخلوط نشویم و وصلت ازدواج صورت نگیرد.\n 💠 فنَکَحنا و اَنکَحنا فِعلَ الاَکفیٰ\n ما با شما هم کفو برخورد کردیم \nدختر دادیم و گرفتیم ولی شما هم کفو ما نبودید.\nما به مصالح و شرایط مجبور بودیم با شما وصلت کنیم .پیامبر از طایفه شما دختر گرفت و دختر داد .مصلحت را بر این دیدیم نه اینکه شما هم کفو ما باشید.\n 💠واَنیٰ یَکونُ ذالِکَ کَذالِک ومِنَا النَّبیُ \nچگونه ما و شما همطراز باشیم در حالیکه شخصیت رسولخدا (ص) از خاندان ماست. وشخص دروغگو ابوجهل از طایفهٔ شما.\n 💠ومِنٰا اَسدُالله و مِنکم اَسدُ الاَحلافِ\nشخصیتی مانند حمزه سیدالشهداء، اسدالله شیر شجاعت است \nشماهم یک اسدی دارید، اما شیر پنبه، نه در شجاعت بلکه در سوگند یاد کردن.\nابوسفیان از دیگر احزاب نیرو جمع میکرد با آنان هم قسم میشد که بر ضد پیامبر در جنگ حاضر باشند.این شیر شما بدنبال عهد و پیمان بود که برضد ما شورش به راه بیندازد.\n 💠مِنا سَیِّدا شَبابِ اَهلِ الجَّنَه و مِنکُم َصبیَهُ النّار\nدر بنی هاشم سید جوانان اهل بهشت از خاندان ما هستند اما در خاندان شما کودکان آتش هستند.\nدر جنگ بدر عُقبه بن ابی مُقیت از سران مشرکین فرد شجاعی بود اما در مقابل لشکر اسلام با چند ضربه کاری که بر او وارد شد لحظه جان دادن فریاد زد : فرزندان من را چه کسی بعد من سرپرستی کند!! (برای تحریک کردن احساسات مردم چنین فریاد زد بچه های من چه میشوند!)\nپیامبر فرمود النار !!\nاگر فرزندان تو در مسیر تو قرار بگیرند آنها هم سزاوار آتشند.\nاین پیشگویی پیامبر محقق شد و یکی از فرزندان اوبنام ولیدبن عقبه ازیاران معاویه است.همین فرزند صبیهُ النار(فرزند آتش) است.\n💠و مِنّا خَیرُ النِّساءِ العالَمِین و مِنکم\nفاطمه (س) خیر النساء از خاندان ماست و ام جمیل همسر ابولهب ، خواهر ابو سفیان، عمه معاویه حماله الحطب از شماست .\n 💠 فِی کثیرٕ مِمّا لَنا وعَلَیکُم \nبسیاری از فضایل در وصف ماهست که اندکی از آن بیان شده .\nوبسیاری از فضاحت و سرافکندگی هم برای تو و طایفه توست. تو از خلفا و بزرگی طایفه خود سخن بمیان آوردی که مرا کوچک کنی .\n 💠 فاِسلامُنا ما قد سُمِع \nکیفیت اسلام ما به گوش همه رسیده، در غربت اسلام با تمام توان ما آنرا یاری کردیم.حتی در دوران جاهلیت وضعیت بنی هاشم غیر قابل انکار است.\nحمزه ،جعفر،ابوطالب ،حتی در جاهلیت موحد بودند.\n 💠کتاب الله یَجمَع لَنا ما شَذَ عَنا \nفضائلی از ما هست که دشمنان میخواستند در تاریخ از بین ببرند اما  قرآن وصف ما را  بیان کرد و ماندگار شد.\n💠وهو قولهُ سبحانه :\n۱. ایه « و اوُلُوالاَرحامِ بعضُهُم اَولیٰ بِبعضٕ فی کتابِ الله »\n « انفال – ۷۵ »\nخاندان نزدیک بعضی بر بعض دیگر اولویت دارند.پسر اولی تر هست بر پسر عمو.\n۲. آیه « اِنَ اَولَی الناسِ بابراهیمَ لَلَذینَ اتَّبَعُوهُ و هٰذَ النبیُ »\n « ال عمران – ۶۸ »\nنزدیکترین افراد به ابراهیم کسانی هستند که از ابراهیم و این پیامبر پیروی کنند.\nاین دو آیه شاهد بر فضل و برتری ماست\n 💠 فنَحنُ مَرَهً اَولیٰ بالقَرابه وتارهٕ اَولیٰ والطاعه\n از جهت قرابت من به پیامبر نزدیکترم از جهت قرآنی” اولو الارحام ” شما قریشی هستید و ما بنی هاشمی\nو از طرف دیگر [تارهً] عامل ، عارف به دین و مطیع محض احکام  پیغمبرم.\nمعاویه تو استدلال به شجره میکنی ما هم شجره هستیم در عین اینکه من ثمره ی این درخت هم هستم.\n💠 ولَمَّا احْتَجَ المهاجرون علی الانصار یوم السقیفه\nدر جریان سقیفه برای جانشینی پیامبر ،مهاجرین(خلفا) برای انصار دلیل آوردند،که ما مهاجرین از اقوام و خویشان پیامبریم و «قرآن هم تایید میکند که اقوام اولی ترند»   \nخلفا این استدلال را آوردند که خلافت را بدست بگیرند.\n💠فَلَجُو علیهِم\n با این دلیل هم  پیروز شدند.\n 💠 فَاِن یَکُن الفَلَجُ به الحقُ لَنا دونَکم\nاگر بنا به خویشاوندی باشد نوبت به خلفا نمی رسید.حق با من بود که قرابت نزدیک داشتم .شما چکاره بودید. بنا به استدلال سقیفه نزدیکترین به پیامبر هم من بودم.\n 💠واِِن یَکن بِغَیرِهِ فلاَنصارُ علیٰ دَعواهُم\nاگر دلیل اهل سقیفه این نبود که از یاران پیامبر انتخاب شود .اقوام درجه یک و دو ندارد ،باید دید چه کسی سزاوارتر است به این مقام .\nشما از پیغمبر بیشتر اطاعت دارید یا ما!! ولی از طرف شما همیشه مخالفت بوده .\nدر هر دو صورت که حساب کنی و جریان سقیفه را بر ضد من بشورانی باز به ضرر خود شماست.\nاگر بگویی سقیفه یک همه پرسی بزرگ جمیع مومنین بوده ،در حالیکه اینگونه نبوده و این استدلال هم بر ضد آنهاست.\nاستدلال امام بر خویشاوندی بنابر قطعیات طرف مقابل است وگرنه همه میدانند قرابت دلیل نیست.\n« اولو الارحام بعضهم ببعض » ابداً اینطور نیست  که نزدیک بودن دلیل خلیفه بودن باشد.آیه « اَولَی الناسِ باِبراهیمُ اتَّبَعُوهُ» ملاک است.\nاما امام به این دلیل، استشهاد به خویشاوندی  می کند!!\nچون شما اینگونه تصور میکنید « هر کس به پیامبر نزدیکتر ,باید خلیفه شود »\nطبق نقل خودتان باز باید من خلیفه می شدم از جهت تبعیت هم باید من می بودم نه شما! \nاین حجتی ست که امام بر ضد مخالفین بکار برده است.\nاللهم اقبلنا مفلحین","بخش سوم\nمتن:\nوَ زَعَمْتَ أَنِّي لِكُلِّ الْخُلَفَاءِ حَسَدْتُ وَ عَلَى كُلِّهِمْ بَغَيْتُ، فَإِنْ يَكُنْ ذَلِكَ كَذَلِكَ فَلَيْسَتِ الْجِنَايَةُ عَلَيْكَ فَيَكُونَ الْعُذْرُ إِلَيْكَ: \"وَ تِلْكَ شَكَاةٌ ظَاهِرٌ عَنْكَ عَارُهَا\". وَ قُلْتَ إِنِّي كُنْتُ أُقَادُ كَمَا يُقَادُ الْجَمَلُ الْمَخْشُوشُ حَتَّى أُبَايِعَ؛ وَ لَعَمْرُ اللَّهِ لَقَدْ أَرَدْتَ أَنْ تَذُمَّ فَمَدَحْتَ، وَ أَنْ تَفْضَحَ فَافْتَضَحْتَ، وَ مَا عَلَى الْمُسْلِمِ مِنْ غَضَاضَةٍ فِي أَنْ يَكُونَ مَظْلُوماً مَا لَمْ يَكُنْ شَاكّاً فِي دِينِهِ وَ لَا مُرْتَاباً بِيَقِينِهِ، وَ هَذِهِ حُجَّتِي إِلَى غَيْرِكَ قَصْدُهَا، وَ لَكِنِّي أَطْلَقْتُ لَكَ مِنْهَا بِقَدْرِ مَا سَنَحَ مِنْ ذِكْرِهَا.\nثُمَّ ذَكَرْتَ مَا كَانَ مِنْ أَمْرِي وَ أَمْرِ عُثْمَانَ، فَلَكَ أَنْ تُجَابَ عَنْ هَذِهِ لِرَحِمِكَ مِنْهُ؛ فَأَيُّنَا كَانَ أَعْدَى لَهُ وَ أَهْدَى إِلَى مَقَاتِلِهِ؟ أَمَنْ بَذَلَ لَهُ نُصْرَتَهُ فَاسْتَقْعَدَهُ وَ اسْتَكَفَّهُ، [أَمَّنِ] أَمْ مَنِ اسْتَنْصَرَهُ فَتَرَاخَى عَنْهُ وَ بَثَّ الْمَنُونَ إِلَيْهِ حَتَّى أَتَى قَدَرُهُ عَلَيْهِ؟ كَلَّا وَ اللَّهِ لَ \"قَدْ يَعْلَمُ اللَّهُ الْمُعَوِّقِينَ مِنْكُمْ وَ الْقائِلِينَ لِإِخْوانِهِمْ هَلُمَّ إِلَيْنا وَ لا يَأْتُونَ الْبَأْسَ إِلَّا قَلِيلًا\". وَ مَا كُنْتُ لِأَعْتَذِرَ مِنْ أَنِّي كُنْتُ أَنْقِمُ عَلَيْهِ أَحْدَاثاً؛ فَإِنْ كَانَ الذَّنْبُ إِلَيْهِ إِرْشَادِي وَ هِدَايَتِي لَهُ، فَرُبَّ مَلُومٍ لَا ذَنْبَ لَهُ: \"وَ قَدْ يَسْتَفِيدُ الظِّنَّةَ الْمُتَنَصِّحُ\". وَ مَا أَرَدْتُ \"إِلَّا الْإِصْلاحَ مَا اسْتَطَعْتُ وَ ما تَوْفِيقِي إِلَّا بِاللَّهِ عَلَيْهِ تَوَكَّلْتُ وَ إِلَيْهِ أُنِيبُ\".\nوَ ذَكَرْتَ أَنَّهُ لَيْسَ لِي وَ لِأَصْحَابِي عِنْدَكَ إِلَّا السَّيْفُ، فَلَقَدْ أَضْحَكْتَ بَعْدَ اسْتِعْبَارٍ؛ مَتَى أَلْفَيْتَ بَنِي عَبْدِ الْمُطَّلِبِ عَنِ الْأَعْدَاءِ نَاكِلِينَ وَ بِالسَّيْفِ مُخَوَّفِينَ؟ \"فَلَبِّثْ قَلِيلًا يَلْحَقِ الْهَيْجَا حَمَلْ\"؛  فَسَيَطْلُبُكَ مَنْ تَطْلُبُ وَ يَقْرُبُ مِنْكَ مَا تَسْتَبْعِدُ؛ وَ أَنَا مُرْقِلٌ نَحْوَكَ فِي جَحْفَلٍ مِنَ الْمُهَاجِرِينَ وَ الْأَنْصَارِ وَ التَّابِعِينَ لَهُمْ بِإِحْسَانٍ، شَدِيدٍ زِحَامُهُمْ سَاطِعٍ قَتَامُهُمْ مُتَسَرْبِلِينَ سَرَابِيلَ الْمَوْتِ، أَحَبُّ اللِّقَاءِ إِلَيْهِمْ لِقَاءُ رَبِّهِمْ؛ وَ قَدْ صَحِبَتْهُمْ ذُرِّيَّةٌ بَدْرِيَّةٌ وَ سُيُوفٌ هَاشِمِيَّةٌ، قَدْ عَرَفْتَ مَوَاقِعَ نِصَالِهَا فِي أَخِيكَ وَ خَالِكَ وَ جَدِّكَ وَ أَهْلِكَ، \"وَ ما هِيَ مِنَ الظَّالِمِينَ بِبَعِيدٍ\".\nترجمه:\nتو چنين پنداشتى که من نسبت به خلفاى پيشين حسد ورزيدم و بر آنها ستم کردم اگر اين گونه باشد جنايتى بر تو نرفته است که از تو عذرخواهى کنم (و ابدا به تو مربوط نيست به گفته شاعر:) «اين عيبى است (اگر عيب باشد) که گرد عار آن بر تو نمى نشيند».\nتو گفته اى که مرا همچون شتر افسار زده اى مى کشيدند تا بيعت کنم به خدا سوگند خواسته اى مذمت کنى ولى (ناخود آگاه) مدح و ثنا گفته اى و خواسته اى رسوا کنى ولى خودت رسوا شده اى. اين امر براى يک مسلمان عيب نيست که مظلوم واقع شود مادام که در دين خود ترديد نداشته باشد و در يقين خود شک نکند. اين دليل و حجت من است در برابر غير تو و من به همين مقدار که بيان آن پيش آمد براى تو اشاره کردم.\nسپس تو وضع مرا در برابر عثمان يادآور شدى (و مرا بر ترک يارى او سرزنش کردى) حق توست که با اين گفتار (نادرست) از خويشاوندت دفاع کنى; ولى کدام يک از ما دشمنيش نسبت به او بيشتر بود و راه را براى کشتنش هموار ساخت؟ آيا کسى که آماده يارى او بود; ولى (او ياريش را نپذيرفت) و از او خواست که بر جاى خود بنشيند و دست از اين کار بکشد و يا کسى که (عثمان) از او يارى خواست و او تأخير کرد و مرگ را به سوى او فرستاد تا زندگانيش به سر آمد؟ هرگز چنين نيست که تو مى گويى (و همه کسانى که در جريان قتل عثمان حضور داشتند اين حقيقت را به خوبى مى دانند.) به خدا سوگند (به شهادت قرآن مجيد) «خداوند کسانى که مردم را (از جنگ) باز مى داشتند و کسانى را که به برادران خود مى گفتند: «به سوى ما بياييد (و خود را از معرکه بيرون کشيد)» به خوبى مى شناسد; آنها (مردمى ضعيف اند و) جز اندکى پيکار نمى کنند».\nولى هرگز سزاوار نبود که من از اين موضوع عذرخواهى کنم که بر عثمان به سبب بدعت هايى که (در تقسيم بيت المال و مناصب کشور اسلامى در ميان نااهلان) گذارده بود عيب گرفتم و او را به علت (اين کارها) سرزنش نمودم. اگر گناه من ارشاد و هدايت او باشد (هيچ مانعى ندارد و اگر به اين کار ملامت شوم افتخار مى کنم) چه بسيار کسانى که ملامت مى شوند و بى گناهند (و به گفته شاعر) گاه شخص ناصح و خيرخواه از بس اصرار در نصيحت مى کند متهم مى شود. «من جز اصلاح ـ تا آنجا که توانايى دارم هدفى نداشته و ندارم ـ و توفيق من (در اين کار)، جز به (يارى) خدا نيست. تنها بر او توکل کردم; و به سوى او باز مى گردم.»\nتو (در نامه خود) گفته اى که نزد تو براى من و يارانم جز شمشير چيزى نيست (و مرا به جنگ تهديد کردى) به راستى بعد از گريه مرا به خنده آوردى! چه زمان ياد دارى که فرزندان عبدالمطلب به دشمن پشت کرده باشند و از شمشير بترسند (و به گفته شاعر): «پس کمى صبر کن که حريفت به ميدان مى آيد»، آرى به زودى آن کس که او را دنبال مى کنى به تعقيب تو بر مى خيزد و آنچه را از آن فرار مى کنى در نزديکى خود خواهى يافت و من در ميان سپاهى عظيم از مهاجران و انصار و تابعان به سرعت به سوى تو خواهم آمد، لشکرى که جمعيتشان به هم فشرده است و به هنگام حرکت غبارشان آسمان را تيره و تار مى کند، آنها لباس شهادت در تن دارند و بهترين ملاقات براى آنها ملاقات با پروردگارشان است و همراه آنها لشکرى از فرزندان بدرند با شمشيرهاى هاشمى که مى دانى لبه تيز آنها با پيکر برادر و دايى و جد و خاندانت چه کرد «و آن (مجازات) از ساير ستمکاران دور نيست.»\nتفسیر:\nمعاویه نامه ای به حضرت نوشت و خواست حضرت را تحریک کند و به نحوی خلفا در مقابل امیرالمومنین قرار بگیرند حضرت پاسخ او را با کمال متانت داد عمروعاص به معاویه مشاوره داد که نامه دوم را بنویسد با الفاظ تندتر و مدح خلفا و مذمت امیرالمومنین با کلماتی که شایسته معاویه بود‌. بازحضرت در پاسخ به نامه دوم در کمال متانت کوبنده ترین پاسخ ها را به معاویه داد.\nبخشی از نامه معاویه:\n ثُمَّ لَم تَکُن أشَدَّ مِنکَ حَسَدا لِابنِ عَمِّکَ عُثمانَ \nتو با همه خلفا دشمن بودی  و به همه آنها خصوص پسر عمویت عثمان حسادت ورزیدی (\nشَرتَ مَقابِحَهُ وطَوَیتَ مَحاسِنَهُ …،\n اگر یک بدی از عثمان سراغ داشتی آنرا در بوق و کرنا می‌کردی و خوبی های فراوان عثمان را پنهان می کردی \nما مِن هؤُلاءِ إلّا مَن بَغَیتَ عَلَیهِ \nهیچکدام از خلفا نبودند مگر اینکه تو به آنها ظلم کردی و بر علیه آنها شوریدی تَلَکَّأتَ فی بَیعَتِهِ حَتّى حُمِلتَ إلَیهِ قَهراً تُساقُ بِخَزائِمِ الاِقتِسارِ کَما یُساقُ الفَحلُ المَخشوشُ \n تا اینکه خلفا تورا مثل یک شتر کشیدند و برای بیعت بردند…\nولَیسَ لَکَ ولِأَصحابِکَ عِندی إلَا السَّیفُ  حرفی باقی نماند بین من و تو جز تیزی شمشیر \nالَّذی لا إلهَ إلّا هُوَ لَأَطلُبَنَّ قَتَلَهَ عُثمانَ أینَ کانوا وحَیثُ کانوا حَتّى أقتُلَهُم أو تَلتَحِقَ روحی بِاللّهِ \n من دنبال قاتلان عثمان می آیم در خشکی و دریا و آنها را پیدا می کنم.\nجواب نامه حضرت : \n🔷وَ زَعَمْتَ أَنِّی لِکُلِّ الْخُلَفَاءِ حَسَدْتُ وَ عَلَى کُلِّهِمْ بَغَیْتُ\nمعاویه بمن نسبت دادی گمان کردی [زعَمتَ]به خلفا حسادت داشتم.\nگمان کردی به آنان ظلم کردم.[بغیتُ]\n🔷فَإِنْ یَکُنْ ذَلِکَ کَذَلِکَ،فَلَیْسَتِ الْجِنَایَهُ عَلَیْکَ\nاگر درست باشد که من ظلم کردم جنایتی بر علیه تو انجام ندادم ،تو چکاره هستی که عذر خواهی کنم.\nحتی اگر خلافی مرتکب شده باشم ،او فرزند ،وکیل ، وصی دارد از آنها باید عذر بخواهم.\n🔷فَیَکُونَ الْعُذْرُ إِلَیْکَ \nچرا باید از تو عذر خواهی کنم!\nمعاویه به تو که ظلم نکردم که بخواهم  عذرخواهی کنم. اگر به دیگران ظلم شده تو چرا مظلوم نمایی می کنی به فرض محال اگر حسادتی بوده، تو چه کاره هستی؟                  \n🔷 وَعَیَّرَها الْواشُونَ أنّى أُحِبُّها\n (عده ای معشوق مرا سرزنش میکنند که من او را دوست دارم)\n🔷وَ تِلْکَ شَکَاهٌ ظَاهِرٌ عَنْکَ عَارُهَا\nاگر عیبی هم در این قضیه باشد از تو دور است بتو کاری ندارد.\n[ کنایه از ارتباط نداشتن به معاویه ]\nمصرع دوم یک بیت شعر بوده،\nکسی عاشق شده در کوچه و بازار عده‌ای معشوق اورا سرزنش کردند.\nمصرع اول آن : \n وَعَیَّرَها الْواشُونَ أنّى أُحِبُّها\n شاعر می گوید خطا از من بوده که عاشق شدم چرا به معشوق من طعنه میزنید؟\nحضرت این مصرع را استفاده کرده اگر زشتی و عیبی باشد به تو ارتباطی ندارد.\nمعاویه می خواهد از حضرت جمله ای در مذمت خلفا بگیرد و آن را بعنوان حربه استفاده کند حضرت هیچگاه خلفا را تایید نکرد ولی هیچگاه بهانه‌ای هم به دست معاویه نداد.\n🔷وَ قُلْتَ إِنِّی کُنْتُ أُقَادُ کَمَا یُقَادُ الْجَمَلُ الْمَخْشُوشُ حَتَّى أُبَایِع!\n((این بخش از جانسوز ترین کلمات حضرت و از مهم‌ترین استدلالات حضرت بر علیه خلفا است دلیل امامت حضرت فراوان است ولی یکی از ادله مهم این جمله است))\nمعاویه تو گفتی در روز بیعتِ با خلیفه، مرا کشاکشان می بردند مانند شتری که افسار او میکشند به اختیار صاحب هر طرف میرود .\nمن علاقه و قبول به این بیعت نداشتم دست مرا بزور در دست او گذاشتند، گفتند بیعت حاصل شد.\nتو این را استدلال کردی مرا مذمت کنی ،که چرا نرفتم با خلیفه بیعت کنم!!\n(مخشوش حلقه ای است که برای رام کردن گاو و شتر به بینی حیوان می زنند کهبا درد بینی شتر بایستد.) \n🔷وَ لَعَمْرُ اللَّهِ لَقَدْ أَرَدْتَ أَنْ تَذُمَّ فَمَدَحْتَ، وَ أَنْ تَفْضَحَ فَافْتَضَحْتَ\nقسم به جان خودم تو خواستی مرا مذمت کنی [اَن تذُم]ولی مرا مدح کردی میخواستی مرا مفتضح کنی در حالی که خود را مفتضح کردی [افتَضَحتَ] جریان خلافت را با این جمله به افتضاح کشاندی\nنکته اول : تو خواستی ظلم و بغی مرا نسبت به خلفا اثبات کنی ولی مظلوم بودن مرا اثبات کردی.\nنکته دوم: تو خواستی اجماع مردم در بیعت با خلفا را ثابت کنی در حالی که معلوم شد همه موافق نبوده اند بلکه با زور از مردم بیعت میگرفتند.\nنکته سوم : خواستی بگویی خلیفه اول بالاترین صحابی پیامبر است، این چه صحابی است که علنا ظلم میکند به صحابی دیگر؟!!\n✳️جریان بیعت گرفتن از امیرالمومنین: \nإِنَّ أَبَا بَکْرٍ أُخْبِرَ بِقَوْمٍ تَخَلَّفُوا عَنْ بَیْعَتِهِ عِنْدَ عَلِیٍّ ع \nبه خلیفه اول خبر رسید که عده‌ای از بیعت با تو سر باز می‌زنند \nفَبَعَثَ إِلَیْهِمْ عُمَرَ بْنَ الْخَطَّابِ فَجَاءَ فَنَادَاهُمْ وَ هُمْ فِی دَارِ عَلِیٍّ \nخلیفه دوم را فرستادبه خانه علی .\nامد وصدا بلند کرد که بیعت کنید.\nطلحه و مقدادگفتند ما با کسی جز علی بیعت نمی کنیم\n فَأَبَوْا أَنْ یَخْرُجُوا فَدَعَا عُمَرُ بِالْحَطَبِ\nعمر گفت هیزم جمع کنید\n فَقَالَ وَ الَّذِی نَفْسُ عُمَرَ بِیَدِهِ لَتَخْرُجُنَّ أَوْ لَأُحْرِقَنَّهَا عَلَیْکُمْ عَلَى مَنْ فِیهَا فَقِیلَ لَهُ یَا أَبَا حَفْصٍ إِنَّ فِیهَا فَاطِمَهَ فَقَالَ وَ إِنْ.\n قسم به کسی که جان عمر در دست اوست، یا بیرون می آیید، و یا خانه را با هر آنکه درون آن است به آتش میکشم. به او گفتند: ای اباحفص! فاطمه علیها السلام درون خانه است. گفت: حتی اگر او هم درون خانه باشد ،آن را به آتش میکشم.\nفَخَرَجُوا فَبَایَعُوا إِلَّا عَلِیٌّ\nهمگی جز علی – علیه السلام – بیرون آمدند و بیعت کردند.\n فَإِنَّهُ زُعِمَ أَنَّهُ قَالَ حَلَفْتُ أَنْ لَا أَخْرُجَ وَ لَا أَضَعَ ثَوْبِی عَلَى عَاتِقِی حَتَّى أَجْمَعَ الْقُرْآنَ\n فرمود: قسم خورده ام تا زمانی که قرآن را جمع آوری نکرده ام بیرون نیایم و لباس بر دوش نیاندازم. \n فَوَقَفَتْ فَاطِمَهُ ع عَلَى بَابِهَا فَقَالَتْ لَا عَهْدَ لِی بِقَوْمٍ حَضَرُوا أَسْوَأَ مَحْضَرٍ مِنْکُمْ\n فاطمه – سلام الله علیها – بر در خانه ایستاد و فرمود: قومی سراغ ندارم که حضوری بدتر از شما داشته باشند؛\n تَرَکْتُمْ جِنَازَهَ رَسُولِ اللَّهِ ص بَیْنَ أَیْدِینَا وَ قَطَعْتُمْ أَمْرَکُمْ بَیْنَکُمْ\n شما پیکر رسول خدا را در میان ما رها کردید و امرتان را بین خودتان تمام کردید.\n لَمْ تُشَاوِرُونَا وَ لَمْ تَرَوْا لَنَا حَقّاً \n و با ما مشورت نکردید و حقی برای ما قائل نشدید.\nفَأَتَى عُمَرُ أَبَا بَکْرٍ فَقَالَ لَهُ أَ لَا تَأْخُذُ هَذَا الْمُتَخَلِّفَ عَنْکَ بِالْبَیْعَهِ\nعمر نزد ابوبکر آمد و به او گفت: آیا نمیخواهی از این متخلف بیعت بگیری؟\n فَقَالَ أَبُو بَکْرٍ یَا قُنْفُذُ وَ هُوَ مَوْلًى لَهُ اذْهَبْ فَادْعُ عَلِیّاً\nابوبکر به قنفذ خدمتکارش  گفت: قنفذ! نزد علی برو و به او بگو برای بیعت بیاید.\n قَالَ فَذَهَبَ قُنْفُذٌ إِلَى عَلِیٍّ ع فَقَالَ مَا حَاجَتُکَ\n قنفذ نزد علی – علیه السلام – رفت، ایشان فرمودند: چه می خواهی؟\n قَالَ یَدْعُوکَ خَلِیفَهُ رَسُولِ اللَّهِ ص \nخلیفه رسول خدا- صلی الله علیه و آله – تو را میخواند.\nقَالَ عَلِیٌّ ع لَسَرِیعٌ مَا کَذَبْتُمْ عَلَى رَسُولِ اللَّهِ \nفرمودند: چه زود بر رسول خدا دروغ بستید.\nفَرَجَعَ قُنْفُذٌ فَأَبْلَغَ الرِّسَالَهَ قَالَ فَبَکَى أَبُو بَکْرٍ طَوِیلًا \nقنفذ برگشت و پیغام را به ابوبکر رساند. ابوبکر مدت زیادی گریه کرد. \nفَقَالَ عُمَرُ الثَّانِیَهَ أَ لَا تَضُمُّ هَذَا الْمُتَخَلِّفَ عَنْکَ بِالْبَیْعَهِ \nعمر برای بار دوم گفت: آیا نمیخواهی این متخلف را برای بیعت بیاوری؟\nفَقَالَ أَبُو بَکْرٍ لِقُنْفُذٍ عُدْ إِلَیْهِ فَقُلْ أَمِیرُ الْمُؤْمِنِینَ یَدْعُوکَ لِتُبَایِعَ\n ابوبکر به قنفذ گفت: نزد علی بازگرد و به او بگو که امیرالمؤمنین تو را برای بیعت فرا میخواند.\n فَجَاءَهُ قُنْفُذٌ فَأَدَّى مَا أُمِرَ بِهِ\n قنفذ آمد و پیغام را رساند.\n فَرَفَعَ عَلِیٌّ صَوْتَهُ فَقَالَ سُبْحَانَ اللَّهِ لَقَدِ ادَّعَى مَا لَیْسَ لَهُ\nعلی – علیه السلام – صدای خود را بلند نموده و فرمود: سبحان الله! چیزی را ادعا کرده که برای او نیست \n فَرَجَعَ قُنْفُذٌ فَأَبْلَغَ الرِّسَالَهَ\nقنفذ بازگشت و پیغام را رساند\n قَالَ فَبَکَى أَبُو بَکْرٍ طَوِیلًا.\n ابوبکر مدت زیادی گریست.\n فَقَالَ عُمَرُ أَمَّا عَبْدُ اللَّهُ فَنَعَمْ وَ أَمَّا أَخَا رَسُولِهِ فَلَا  وَ أَبُو بَکْرٍ سَاکِتٌ لَا یَتَکَلَّمُ.\nسپس عمر برخاست و به همراه عده ای راه افتادبه در خانه فاطمه  در زدند.\n وقتی فاطمه صدای آنها را شنید، گریه کنان و با صدای بلندی فریاد برآورد: ای رسول خدا! بعد از تو چه ها از پسر خطاب و پسر ابیقحافه چه ها دیدیم،\n وقتی مردم صدا و گریه ایشان را شنیدند، گریه کنان از آنجا برگشتند، و نزدیک بود دلهایشان پاره پاره شود و جگرهایشان تکه تکه گردد.\n عمر به همراه عده ای در آنجا ماندند و علی علیه السلام را بیرون آوردند و ایشان را نزد ابوبکر بردند و گفتند بیعت کن، ایشان فرمودند: اگر این کار را نکنم، چه میشود؟ گفتند: به خداوند که معبودی جز او نیست سوگند اگر بیعت نکنی گردنت را می زنیم.\n فرمود: در این صورت بنده خدا و برادر رسول خدا را کشته اید. \nعمر گفت: بنده خدا را آری، ولی برادر رسول خدا را نه. ابوبکر دم فرو بسته بود و چیزی نمیگفت.\n🔷وَ مَا عَلَى الْمُسْلِمِ مِنْ غَضَاضَهٍ  فِی أَنْ یَکُونَ مَظْلُوماً؛ مَا لَمْ یَکُنْ شَاکّاً فِی دِینِهِ وَ لَا مُرْتَاباً بِیَقِینِهِ \nبر هیچ مسلمانی عیب، خواری و ننگ[غضاضه] نیست که مظلوم واقع بشود‌.،ظلم کردن عیب است.\nدر مظلوم بودن مذمتی نیست ،بشرطی که در دین شک[شاکاً] نکند و در یقین او تردید ایجاد نشود.[لامرتاباً] آنها به من ظلم کردند و مرا کشان کشان بردند.\nدر خطبه ۱۵۱ هم فرموده : َ\n اقْدَمُوا عَلَى اللَّهِ مَظْلُومِینَ وَ لَا تَقْدَمُوا عَلَیْهِ ظَالِمِین‏.\nمظلوم واقع شدن گاهی با شک در دین حاصل میشود، در این موقع مظلوم واقع نشوید و حق خودتان را کاملا بگیرید (ولی ظلم هم نکنید) \nمن برای اینکه عده‌ای بیگناه را نکشم حاضرم خود کشته شوم این فخر و مردانگیست .ظلم کردن ذلت است .\n من مظلوم واقع شدم سربلند شدم وای به حال کسانی که دست بسته بردند و به زور از مسلمان ها بیعت گرفتند.\n انسان اگر سر دوراهی ظالم بودن یا مظلوم بودن باشد مظلوم بودن بهتر است.\nنکته : حضرت فرمود به شرط اینکه در دین و یقین شما شک  بوجود نیاید بعضی  ظرفیتشان تا زمانی است که به آنها ظلم نشود کوچکترین ظلم به آنها باعث درگیری با خدا می شود اگر ظرفیت مظلوم شدن را ندارید باید حق خود را بگیرید ظلم نکنید ولی حق خود را بگیرید  حتی مظلوم شدن هم ظرفیت میخواهد\n داد .\nبنا نیست تو سری خور باشیم باید ظرفیت داشت  ” رُدُ الحَجَر مِن حیثُ جاءَ ” سنگ را از هر طرف زدند از همان طرف برگردانید ولی انسان  جایی مجبور شد به مظلوم ماندن یا ظلم کردن . استیفای حق ممکن نبود در اینحالت مظلوم شدن شرافت دارد‏.\n 🔷وَ هَذِهِ حُجَّتِی إِلَى غَیْرِکَ قَصْدُهَا\n این دلیل من در اثبات خلافت خویش است در مقابل خلفای که تو از آنها دفاع کردی_البته  منظورم تو نیستی چون تو اصلا قابل مقایسه با من نیستی که بخواهم برای اثبات حقانیت خویش در مقابل تو استدلال کنم.\nمعاویه تو مسیر لجاجت با من را انتخاب کردی این حرفها را نمی پذیری.\nاین سخن نه برای تو، بلکه برای آیندگان میزنم آنان که می شنوند و دنبال حقیقت هستند. در تو هیچ ارشادی اثر ندارد. \n🔷وَ لَکِنِّی أَطْلَقْتُ  لَکَ مِنْها بقدر ما سنح مِنْ ذِکْرِهَا\nاین حجتی که اقامه کردم به اندازه دو جمله ای بود که از ذهنم خطور کرد برای تو نوشتم و مقصودم آیندگان بودند.\nقصد این نبود که صد در صد کیفیت انتخاب خلیفه و مخالفت خود را بیان کنم . دو جمله از خطور ذهنم بود[سنَحَ]\n🔷ثُمَّ ذَکَرْتَ مَا کَانَ مِنْ أَمْرِی وَ أَمْرِ عُثْمَانَ \nتو مرا متهم کردی به قتل عثمان پسر عموی من خطاب کردی که چرا از او دفاع نکردم .\n🔷 فَلَکَ أَنْ تُجَاب عَنْ هَذِه لِرَحِمِکَ مِنْهُ\nسزاوار است تو جواب دهی که چگونه از خویشاوند خود یعنی عثمان دفاع نکردی\nو جلوی شورش را نگرفتی.\n 🔻 نکته ۱) \nمن هیچ قرابتی با عثمان ندارم، عثمان را به من وصل نکن . با عثمان نسبت تدارم انها فرزندان یک غلام  رومی هستند هیچ نسبتی با آل پیامبر ندارند(رجوع شود ذیل خطبه ۱۷ )\nنکته ۲)\nمتهم کردی نسبت به عثمان کم گذاشته و کوتاهی کردم تو برای عثمان چه کردی؟\n🔷 فَأَیُّنَا کَانَ أَعْدَى لَهُ وَ أَهْدَى إِلَى مَقَاتِلِهِ؟ \nکدام یک از ما دونفر بیشتر او را هدایت به سمت مرگ کردیم؟\nکدامیک از ما بر عثمان دشمن تربودیم .\nوکدامیک از ما مردم را هدایت کرد به کشتن عثمان!!  \n🔷 أَمَ مَنْ بَذَلَ لَهُ نُصْرَتَه فَاسْتَقْعَدَهُ وَ اسْتَکَفَّهُ ، أَمْ مَنِ اسْتَنْصَرَهُ \nیک گروه آمد به عثمان کمک کند ولی عثمان نپذیرفت .گفت از شهر بیرون برو ،به کمک تو نیازی نیست، ازمن دست بکش. (آن من بودم )\nمن تمام تلاشم را برای دفاع عثمان کردم عثمان درخواستم را رد کرد فرق است بین من و کسی که عثمان از او طلب کمک کرد\n🔷 فَتَرَاخَى عَنْهُ  وَ بَثَّ الْمَنُونَ إِلَیْهِ حَتَّى أَتَى قَدَرُهُ عَلَیْهِ؟ \n[تراخی]\nگروه دیگر ،وضعیت توست ،عثمان در نامه ای از تو کمک خواست طلب یاری کرد  به کمک او نشتافتی تا مرگ او فرا رسید. بعد از  مرگ خونخواه او شدی .\nتو شریک قتل او هستی از طرف او حاکم شام بودی تو چرا دفاع نکردی!!\n✅ کار رسانه اینست معاویه که در جریان قتل عثمان متهم و در خلاف هم  شریک بود و به او کمک هم نکرد اکنون حضرت را متهم به قتل عثمان می کند.\n🔷 کَلَّا وَ اللَّهِ ” لَقَدْ یَعْلَمُ اللَّهُ الْمُعَوِّقِینَ مِنْکُمْ وَ الْقائِلِینَ لِإِخْوانِهِمْ هَلُمَّ إِلَیْنا وَ لا یَأْتُونَ الْبَأْسَ إِلَّا قَلِیلًا “\nاستشهاد حضرت به آیه قرآن”احزاب – ۱۸”\nقطعا خدا میداند منافقین که از جنگ احزاب عقب نشستند و در گوش برادران خود زمزمه می کردند عقب برگردید ،بنزد ما بیایید‌وخود در جنگ حاضر نمی شدند مگر عدد محدود آنهم برای ریا ‌.\n منافق این گونه است برای اینکه به دام نیفتد دیگران را به دام می اندازد و متهم میکند. شما از منافقین هستید که جایی که باید باشید نیستید و کسانی که میخواهند کاری انجام دهد جلوی آنها را می گیرید\n✳️خطبه ۲۴۰ : \nیَا ابْنَ عَبَّاسٍ مَا یُرِیدُ عُثْمَانُ إِلَّا أَنْ یَجْعَلَنِی جَمَلًا نَاضِحاً بِالْغَرْبِ أَقْبِلْ وَ أَدْبِرْ بَعَثَ إِلَیَّ أَنْ أَخْرُجَ ثُمَّ بَعَثَ إِلَیَّ أَنْ أَقْدُمَ ثُمَّ هُوَ الْآنَ یَبْعَثُ إِلَیَّ أَنْ أَخْرُجَ وَ اللَّهِ لَقَدْ دَفَعْتُ عَنْهُ حَتَّى خَشِیتُ أَنْ أَکُونَ آثِما.\nحضرت به ابن عباس گلایه می کند‌\n بخدا قسم عثمان مرا مثل شتری که آبکشی می کند طناب به گردن انداخته و به سمت چاه می فرستد همین که از آب چاه کشید دوباره او را برمی گرداند. به من گفت بیا مدینه و دوباره گفت از شهر خارج شو. من آنقدر  دفاع کردم که ترسیدم گناهکار شوم .\n🔷وَ مَا کُنْتُ لِأَعْتَذِرَ \nاگر بناست بخاطر کار خوب محکوم شوم هیچ باکی نیست.\n 🔷مِنْ أَنِّی کُنْتُ أَنْقِمُ عَلَیْهِ أَحْدَاثا\n سزاوار نیست عذرخواهی کنم از کسی که از بدعت های او [اَحداث] عیب می گرفتم چون عثمان اهل بدعت گذاری بود.\n🔷 فَإِنْ کَانَ الذَّنْبُ إِلَیْهِ إِرْشَادِی وَ هِدَایَتِی لَهُ\nاگر رفتن بنزد عثمان و نصیحت و خیر خواهی به او ، برای امر به معروف و هدایت کردنم ،عذر خواهی کنم هیچ باکی نیست. گناه من بخاطرارشاد و هدایت عثمان باشد.\n🔷 فَرُبَّ مَلُومٍ لَا ذَنْبَ له\nچه بسیار کسانی که ملامت می شوند در حالی که بی گناه هستند\n🔷وَ قَدْ یَسْتَفِیدُ الظِّنَّهَ الْمُتَنَصِّحُ       \nچه بسیار که شخص نصیحت کننده خیرخواه مورد تهمت واقع میشود.\nمن خیر خواهی کردم برای عثمان ،تو زبان گشودی به مذمت من.\nابایی ندارم واین باعث مدح من میشود و مقام مرا بالا می برد.\n🔷 وَ مَا أَرَدْتُ “إِلَّا الْإِصْلاحَ مَا اسْتَطَعْتُ وَ ما تَوْفِیقِی إِلَّا بِاللَّهِ عَلَیْهِ تَوَکَّلْتُ وَ إِلَیْهِ أُنِیبُ”.\n ” هود – ۶۸ “\nمن هیچ قصدی ندارم جز اصلاح امت،هر قدر که توانایی دارم.\nو توفیقی نیست مگر از طرف خداوند .\nبراو توکل می کنم وباژگشتم بسوی اوست.\n🔷وَ ذَکَرْتَ أَنَّهُ لَیْسَ لِی وَ لِأَصْحَابِی عِنْدَکَ إِلَّا السَّیْفُ\nمعاویه  مرا تهدید کرد  که بین من و تو جز شمشیر حاکم نیست،\n🔷فَلَقَدْ اضحکت بعد استعبار!\nمعاویه؛ بعد از گریه مرا بخنده انداختی حرفت بسیار دور از واقعیت است.\n🔷مَتَى أَلْفَیْتَ بَنِی عَبْدِ الْمُطَّلِبِ عَنِ الْأَعْدَاءِ نَاکِلِینَ وَ بِالسَّیْفِ مُخَوَّفِینَ ؟\nکی در تاریخ سراغ داری و چنین یافتی [اَلفیتَ] که فرزندان عبدالمطلب از جنگ بر دشمن پشت کنند[ناکلین] و بخواهند ما را با شمشیر بترسانند [مخوفّین]ما با وعده جنگ و تحریم بترسیم تاریخ  چنین چیزی ندیده\nزره حضرت فقط جلو داشت  سوال شد چرا زره شما پشت ندارد!! فرمود: \n دشمن که نمی تواند هیچ گاه مرا دور بزند و من هیچگاه پشت به دشمن نمی کنم که بخواهد از پشت بمن ضربه بزند.\n✅ زمانی که حضرت معاویه را به جنگ تن به تن دعوت کرد عمروعاص میگوید: من  بودم و دیدم چه افتضاحی به بار آمد  مردی به میدان بیا! در خطبه ۲۲ آمده : لَقَدْ کُنْتُ وَ مَا أُهَدَّدُ بِالْحَرْبِ وَ لَا أُرْهَبُ بِالضَّرْبِ وَ إِنِّی لَعَلَى یَقِینٍ مِنْ رَبِّی وَ غَیْرِ شُبْهَهٍ مِنْ دِینِی‏\nتا بوده چنین بوده هیچ احدی نمی تواند مرا به زد و خورد تهدید کند امروز که حاکم هستم و لشکر دارم و مرد جنگ آزموده هستم معاویه میخواهد مرا تهدید کند؟ این بسیار خنده دار است\nیک مصرع را حضرت فرمود.\n🔷فَ” لَبِّثْ قَلِیلًا یَلْحَقِ الْهَیْجَا حَمَلْ”\n      کمی صبر کن [لبِّث ]حَمَل وقتی وارد معرکه شود زیباست.\n(ضرب المثل: شخصی به نام حمَل که شترهایش دزدیده شده بودند،او تنهای تنها به دزدان شبیخون زد و اموالش را پس گرفت و چنین بیتی را سرود)\nفرمود : من هم مثل حمَل وقتی به معرکه وارد شوم همه را تار ومار میکنم.\n🔷ما أحْسَنَ الْمَوْتُ إذَ الْمَوْتُ نَزَل       \nدر چنین حالتی اگر مرگ پیش آید چه  مرگ زیبایی است.\n 🔷فَسَیَطْلُبُکَ مَنْ تَطْلُبُ وَ یَقْرُبُ مِنْکَ مَا تَسْتَبْعِدُ\nمعاویه هشدار داده بودی بزودی بسمت ما خواهی آمد برای گرفتن قاتلان عثمان! به زودی قاتلان به سراغ تو می آیند[سیَطلبُک] و آنچه را که تو دور می پنداشتی [تَستَبعِد]به تو نزدیک می شود.\n🔷وَ أَنَا مُرْقِلٌ نَحْوَکَ فِی جَحْفَلٍ مِنَ الْمُهَاجِرِینَ وَ الْأَنْصَارِ وَ التَّابِعِینَ لَهُمْ بِإِحْسَانٍ، \n من در یک لشکر عظیمی[جَحفل] از مهاجرین و انصار و تابعین بسرعت[مُرقِل] نزد تو می آییم . \n(صحابی پیامبر برخی از مهاجرین و انصار پیامبر را ندیدند ولی مهاجرین و انصار را دیدند انها تابعین هستند البته مهاجرین و انصار همه صحابی پیامبر نیستند کسانی که مهاجرین و انصار را دیدند هم تابعین نیستند تابعین باحسان یعنی دنباله رو پیامبر هستند) \nمن در لشکر بزرگی از مهاجرین و انصار و تابعین به سمت تو می آیم\n🔷شَدِیدٍ زِحَامُهُمْ \nهمان‌هایی که جمعیت شان فشرده[زِحام] است.\n🔷 سَاطِعٍ قَتَامُهُمْ \nکسانی که وقتی راه می روند از شدت جمعیت غبار آسمان را فرا میگیرد.[ساطع]\n🔷 مُتَسَرْبِلِینَ سَرَابِیلَ الْمَوْتِ\nکسانی که کفن یا لباس [سرابیل] شهادت به تن کرده اند \n🔷 أَحَبُّ اللِّقَاءِ إِلَیْهِمْ لِقَاءُ رَبِّهِمْ؛\nو بهترین دیدار برای آنها دیدار با خداست.\n🔷 وَ قَدْ صَحِبَتْهُمْ ذُرِّیَّهٌ بَدْرِیَّهٌ \nبدان در این لشکر عظیم مهاجرین و انصار و تابعین بچه های جنگ [ذریهً بدریهً] همانها که فرزندان جنگ بدرند همراهی می‌کنند. در میان مهاجرین کسانی هستند که بدر را درک کردند.\n🔷وَ سُیُوفٌ هَاشِمِیَّهٌ\nشمشیرهای آنها هاشمی ست\n🔷قَدْ عَرَفْتَ مَوَاقِعَ نِصَالِهَا فِی أَخِیکَ  وَ خَالِکَ وَ جَدِّکَ وَ أَهْلِکَ\nهمان هایی که تیزی شمشیر[نِصالها] آنها را چشیدی در مورد برادرت (حنظله ابن ابی سفیان ) و دایی تو ( ولید بن عتبه) \nو پدربزرگ مادری تو (عتبه بن ربیعه ، پدر هند جگرخوار)  شمشیر هاشمی را خورده اند امروز من با این دوستان به سمت شما میآیم.\n🔷وَ ما هِیَ مِنَ الظَّالِمِینَ بِبَعِیدٍ”. \nحضرت فرمود عذابی که خدا بر قوم لوط نازل کرد بر بقیه ظالمین هم نازل می شود و عذاب از ظالمین دور نیست.\nاین نامه از بهترین نامه ها هم از لحاظ ادبی و بلاغی و هم جملاتی که در منکوب کردن شبهات معاویه بکار برده، بهترین  می باشد.\nاللهم عجل لولیک الفرج"]});
